INSERT INTO quiz_questions (id, topic_id, level_number, statement, answer, hint, explanation, fun_fact, source, status, reviewed_by, active, updated_at) VALUES
  ('my-cycle-1-01', 'my-cycle', 1, 'Anywhere from 2 to 7 days counts as a normal-length period.', 'fact', 'Think ‘about a week, give or take’.', 'Yep! Most periods last 2 to 7 days. If yours often goes past 7, it’s worth a chat with a doctor.', 'Your very first period even has its own name: menarche.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-02', 'my-cycle', 1, 'Day 1 of your cycle is the first day you bleed, not the day it ends.', 'fact', 'Where does the countdown start?', 'Spot on. Day 1 is the first day of proper bleeding, and the cycle runs until the day before your next one.', 'That’s why logging day 1 is the magic that lets Spot it predict your next period.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-03', 'my-cycle', 1, 'A ‘proper’ cycle is exactly 28 days, every single time.', 'myth', 'Are all bodies on the same timetable?', 'Nope! Anything from about 21 to 35 days is common, and yours can wobble a little month to month.', '28 days is just an average. Lots of people never hit it exactly.', 'ACOG: Menstruation in girls and adolescents', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-04', 'my-cycle', 1, 'Periods can be all over the place for the first year or two.', 'fact', 'Your body is still learning the routine.', 'Totally normal. Hormones take a while to settle into a rhythm, so early cycles can change length a lot.', 'For many people, cycles become more predictable a few years after periods start.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-05', 'my-cycle', 1, 'You lose about a whole cup of blood every period.', 'myth', 'It looks like more than it is.', 'Way less! Most people lose around 2 to 3 tablespoons over the whole period.', 'It looks like more because period blood is mixed with womb lining and mucus.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-06', 'my-cycle', 1, 'A tiny bit of spotting between periods always means something’s wrong.', 'myth', 'Light spotting can have everyday causes.', 'Not always. Light spotting can happen around ovulation or with some medicines. If it keeps happening or worries you, see a doctor.', 'Logging spotting in Spot it helps you see if it follows a pattern.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-07', 'my-cycle', 1, 'Little jelly-like clots in period blood can be completely normal.', 'fact', 'Think about heavier days.', 'True. Small clots are common on heavy days. Ones bigger than about 2.5 cm are worth mentioning to a doctor.', 'The heaviest days are usually the first one or two days of a period.', 'NHS: Heavy periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-08', 'my-cycle', 1, 'A stressful exam week can actually make your period late.', 'fact', 'Your brain helps run the show.', 'It really can. Stress, big changes in weight or lots of exercise can shake up the hormones that time your cycle.', 'Travel and changes in sleep can nudge your cycle too.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-09', 'my-cycle', 1, 'Period blood should always be bright red.', 'myth', 'Think about what happens to blood that’s been around a little while.', 'Nope! Bright red, dark red, pink or brown are all normal. Brown is just older blood that took its time leaving.', 'Brown blood is common at the very start or end of a period.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-1-10', 'my-cycle', 1, 'It’s normal for your period to turn up a few days earlier or later than you expected.', 'fact', 'Are bodies clockwork?', 'Yep! Cycles can shift by a few days from month to month, especially in your first few years.', 'Logging a few cycles helps Spot it learn your own rhythm.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-01', 'my-cycle', 2, 'Everyone ovulates on day 14. It’s basically a rule.', 'myth', 'Is every cycle the same length?', 'Myth! Ovulation moves with your cycle length. Day 14 is only the average for a 28-day cycle.', 'If your cycle is 35 days, ovulation is more likely around day 21.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-02', 'my-cycle', 2, 'Ovulation is the moment one of your ovaries releases an egg.', 'fact', 'The word comes from the Latin for egg.', 'Yep. Each cycle your hormones signal an ovary to let an egg go. That’s ovulation.', 'An egg is one of the biggest cells in the human body, just about visible without a microscope.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-03', 'my-cycle', 2, 'Once an egg is released, it hangs around for about a week.', 'myth', 'It’s a lot shorter than you’d think.', 'Myth. An egg only survives about 12 to 24 hours after it’s released. If it isn’t fertilised, it breaks down.', 'Most of the time, only one egg is released each cycle.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-04', 'my-cycle', 2, 'Ovulation usually happens about 12 to 16 days before your next period.', 'fact', 'Try counting backwards.', 'True. The time after ovulation is fairly steady, so counting back from your period is a good clue.', 'That steady second half of the cycle usually lasts about two weeks.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-05', 'my-cycle', 2, 'Some people feel a little twinge on one side of their tummy when they ovulate.', 'fact', 'It even has a German name: mittelschmerz.', 'It’s real! Ovulation pain is common, harmless and usually lasts minutes to a day or two. See a doctor if it’s severe.', 'Mittelschmerz literally means ‘middle pain’, because it happens mid-cycle.', 'NHS: Ovulation pain', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-06', 'my-cycle', 2, 'You usually ovulate while you’re on your period.', 'myth', 'Think middle, not start.', 'Myth. For most people ovulation happens around the middle of the cycle, well after bleeding has stopped.', 'Ovulation usually happens about two weeks before your next period starts.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-07', 'my-cycle', 2, 'Around ovulation, discharge can turn clear and stretchy, a bit like raw egg white.', 'fact', 'Your body leaves clues.', 'True. Rising oestrogen makes the mucus thinner and stretchier around ovulation.', 'Some people use this ‘egg white’ clue to spot when they’re ovulating.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-08', 'my-cycle', 2, 'Your body temperature drops after you ovulate.', 'myth', 'One hormone is a bit of a heater.', 'Other way round! Progesterone nudges your resting temperature up slightly after ovulation, until your period.', 'The rise is tiny, usually less than half a degree.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-09', 'my-cycle', 2, 'Ovulation can happen from either ovary, and they don’t strictly take turns.', 'fact', 'Is there a rota?', 'True! Each cycle one ovary usually releases an egg, but it isn’t a neat left-right-left pattern.', 'Some people notice their mid-cycle twinge switches sides, but not always.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-2-10', 'my-cycle', 2, 'Everyone can feel the exact moment their egg is released.', 'myth', 'How many people do you know who mention it?', 'Nope! Most people feel nothing. Some get a one-sided twinge called mittelschmerz, which is German for ‘middle pain’.', 'Mittelschmerz can last from a few minutes to a day or two.', 'NHS: Ovulation pain', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-01', 'my-cycle', 3, 'Your cycle has four ‘seasons’: period, build-up, ovulation and the run-up to your next period.', 'fact', 'Bleed, build, release, wait.', 'Exactly. Doctors call them the menstrual, follicular, ovulation and luteal phases.', 'Some people notice their energy changes with each phase.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-02', 'my-cycle', 3, 'The ‘PMS week’ comes before you ovulate.', 'myth', 'When does progesterone take over?', 'Myth. It comes after. Once the egg is out, progesterone rises, and that’s when bloating and mood dips can creep in.', 'The luteal phase is named after the corpus luteum, Latin for ‘yellow body’.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-03', 'my-cycle', 3, 'The build-up phase starts on the very first day of your period.', 'fact', 'It overlaps with bleeding.', 'True! While you bleed, a new egg is already getting ready. Doctors call this the follicular phase.', '‘Follicle’ comes from a Latin word meaning ‘little bag’.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-04', 'my-cycle', 3, 'PMS usually shows up in the week or two before your period.', 'fact', 'Think end of the cycle.', 'Yep. Bloating, sore boobs and mood swings usually start late in the cycle and ease once bleeding starts.', 'Most women and girls notice at least one PMS symptom at some point.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-05', 'my-cycle', 3, 'Oestrogen climbs higher and higher as an egg gets ready.', 'fact', 'This hormone is the builder.', 'True. The growing follicle pumps out more and more oestrogen, which peaks just before ovulation.', 'That oestrogen peak is what helps trigger ovulation.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-06', 'my-cycle', 3, 'Progesterone is busiest during your period.', 'myth', 'When is it actually made?', 'Myth. Progesterone is made after ovulation and drops just before your period, which is partly what starts it.', 'Progesterone’s name comes from ‘pro-gestation’, because it supports pregnancy.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-07', 'my-cycle', 3, 'No fertilised egg means the womb lining gets shed. Hello, period.', 'fact', 'What happens to the lining?', 'Exactly. When hormones fall at the end of the cycle, the lining comes away and leaves the body as your period.', 'The womb lining has a science name: the endometrium.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-08', 'my-cycle', 3, 'When cycles change length, it’s usually the second half that changes.', 'myth', 'Which half is the steady one?', 'Myth. The second half usually stays steady at around 11 to 17 days. The first half is what stretches or shrinks.', 'That’s why a late period usually means ovulation happened later than usual.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-09', 'my-cycle', 3, 'The part of your cycle after ovulation is called the luteal phase.', 'fact', 'It’s named after something yellow.', 'Yep! It’s named after the corpus luteum, the ‘yellow body’ left behind in the ovary after an egg is released.', '‘Luteum’ is Latin for yellow.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-3-10', 'my-cycle', 3, 'Your womb lining stays the same thickness all month.', 'myth', 'What does your period actually shed?', 'Nope! The lining builds up after your period, gets thicker after ovulation, then sheds if there’s no pregnancy.', 'The lining can grow several times thicker in a single cycle.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-01', 'my-cycle', 4, 'A cycle can be ‘regular’ even if it isn’t 28 days long, as long as its length stays fairly steady.', 'fact', 'Regular means predictable.', 'Correct! A steady 32-day cycle is just as regular as a 28-day one.', 'Doctors usually call adult cycles of 21 to 35 days typical.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-02', 'my-cycle', 4, 'Your cervix changes position and feel across your cycle.', 'fact', 'Is your body static?', 'Correct! Around ovulation the cervix tends to sit higher and feel softer, then lower and firmer afterwards.', 'Some people track this as a fertility sign.', 'Cleveland Clinic: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-03', 'my-cycle', 4, 'The womb lining can grow several times thicker between the end of your period and ovulation.', 'fact', 'Oestrogen is a builder.', 'Correct! Rising oestrogen builds the lining up from very thin after a period to many times thicker.', 'Doctors can measure the lining on an ultrasound.', 'Cleveland Clinic: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-04', 'my-cycle', 4, 'The hormone surge that triggers ovulation comes from the ovaries.', 'myth', 'Which gland sends the ‘go’ signal?', 'Wrong one! The LH surge comes from the pituitary gland in your brain. The ovaries respond to it.', 'The pituitary is about the size of a pea.', 'Cleveland Clinic: Luteinizing hormone', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-05', 'my-cycle', 4, 'After ovulation, the empty follicle becomes the corpus luteum, which makes progesterone.', 'fact', 'Leftovers with a job.', 'Correct! The empty follicle turns into a temporary gland that pumps out progesterone.', 'Corpus luteum means ‘yellow body’ in Latin.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-06', 'my-cycle', 4, 'If you don’t ovulate in a cycle, you can’t have any bleeding.', 'myth', 'Is every bleed a true period?', 'Not true! Bleeding can still happen without ovulation. It’s called an anovulatory bleed, and it’s common in the first few years of periods.', 'It’s also common around perimenopause.', 'Cleveland Clinic: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-07', 'my-cycle', 4, 'Your resting body temperature rises by roughly 0.2 to 0.5°C after ovulation.', 'fact', 'Progesterone is a heater.', 'Correct! Progesterone nudges your resting temperature up slightly, and it stays up until your next period.', 'Some people track this every morning as a fertility sign.', 'NHS: Ovulation and fertility', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-08', 'my-cycle', 4, 'Ovulation tests detect oestrogen in your pee.', 'myth', 'Which hormone surges?', 'Not quite! Most ovulation tests detect the LH surge, which comes 1 to 2 days before ovulation.', 'Some newer tests also check an oestrogen marker.', 'Cleveland Clinic: Ovulation', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-09', 'my-cycle', 4, 'Chemicals called prostaglandins, released by the womb lining, make the womb contract during your period.', 'fact', 'What makes the squeeze?', 'Correct! Prostaglandins make the womb muscles tighten. More prostaglandins can mean stronger cramps.', 'Ibuprofen works by lowering prostaglandins.', 'ACOG: Dysmenorrhea', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-4-10', 'my-cycle', 4, 'Your ovaries make brand-new eggs every month.', 'myth', 'Is the supply topped up?', 'Not true! You’re born with all the immature eggs you’ll ever have. Each cycle, a few start to grow.', 'Your eggs formed before you were even born.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-01', 'my-cycle', 5, 'Out of 1 to 2 million eggs at birth, only around 400 to 500 will ever be released.', 'fact', 'Most never get the call.', 'Correct! The rest naturally fade away over time. Only a few hundred are ever ovulated.', 'That’s roughly one egg for each cycle in your life.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-02', 'my-cycle', 5, 'By puberty, you still have about the same number of eggs you were born with.', 'myth', 'Does the number shrink?', 'Not true! By puberty there are only about 300,000 to 400,000 left.', 'Eggs are lost naturally all through childhood.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-03', 'my-cycle', 5, 'The LH surge usually happens about 24 to 36 hours before ovulation.', 'fact', 'Is it the same moment?', 'Correct! The egg is usually released a day or so after the LH surge starts.', 'That’s why a positive ovulation test means ‘soon’, not ‘now’.', 'Cleveland Clinic: Luteinizing hormone', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-04', 'my-cycle', 5, 'Around ovulation, cervical mucus is at its thickest and stickiest.', 'myth', 'Think egg white.', 'Backwards! Around ovulation it’s at its thinnest, clearest and stretchiest. It thickens after ovulation.', 'Progesterone is what makes it thick again.', 'Cleveland Clinic: Cervical mucus', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-05', 'my-cycle', 5, 'Several follicles start growing each cycle, but usually only one becomes the dominant follicle that releases an egg.', 'fact', 'Only one wins.', 'Correct! One follicle pulls ahead and the others stop growing.', 'When two win, non-identical twins can happen.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-06', 'my-cycle', 5, 'If the luteal phase is short, the follicular phase must be long to make up for it.', 'myth', 'Are the two halves linked?', 'Not true! The two phases aren’t balanced against each other. Cycle length varies mostly because of the follicular phase.', 'A short luteal phase can be a sign of low progesterone.', 'Cleveland Clinic: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-07', 'my-cycle', 5, 'In a study of more than 600,000 cycles, only about 13% were exactly 28 days long.', 'fact', 'Is 28 the norm?', 'Correct! A big study using app data found most cycles weren’t 28 days, and the average was about 29.', 'The study used data from over 120,000 people.', 'Bull et al., npj Digital Medicine (2019)', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-08', 'my-cycle', 5, 'The corpus luteum keeps making progesterone for the rest of the cycle no matter what.', 'myth', 'What happens if there’s no pregnancy?', 'Not true! Without a pregnancy it breaks down after about 10 to 14 days. Progesterone falls and a period starts.', 'If there is a pregnancy, hCG keeps it going.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-09', 'my-cycle', 5, 'In early pregnancy, the hormone hCG keeps the corpus luteum making progesterone.', 'fact', 'Pregnancy tests look for it.', 'Correct! hCG tells the corpus luteum to keep going until the placenta takes over.', 'Home pregnancy tests detect hCG in pee.', 'Cleveland Clinic: hCG', 'approved', 'Spot it content team', true, now()),
  ('my-cycle-5-10', 'my-cycle', 5, 'Spotting around ovulation happens because the egg tears through the ovary and bleeds out.', 'myth', 'Think about hormone levels.', 'Not quite! Mid-cycle spotting is thought to be caused by the brief dip in oestrogen around ovulation, not by bleeding from the ovary.', 'Only a small number of people notice ovulation spotting.', 'Cleveland Clinic: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-01', 'period-myths', 1, 'You shouldn’t go swimming on your period.', 'myth', 'Think about what a tampon or a cup does.', 'Myth! Swimming is fine with a tampon or a cup, and moving can even ease cramps.', 'Water pressure can slow your flow a little while you’re in the pool.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-02', 'period-myths', 1, 'Exercise makes period cramps worse.', 'myth', 'Moving helps muscles relax.', 'Myth. Gentle exercise like walking, swimming or stretching can actually ease period pain.', 'Exercise releases endorphins, your body’s own feel-good painkillers.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-03', 'period-myths', 1, 'If you live with friends or family, your periods will sync up.', 'myth', 'What does the research say?', 'It’s a popular idea, but bigger studies haven’t found good evidence that periods sync.', 'Cycles naturally drift in and out of line, which makes it look like syncing now and then.', 'ACOG: Menstruation in girls and adolescents', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-04', 'period-myths', 1, 'A warm shower or bath during your period is totally fine.', 'fact', 'Warm water might even feel nice.', 'True! Washing helps you feel fresh, and a warm bath may ease cramps.', 'Warmth helps the womb muscles relax, which is why a bath can soothe cramps.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-05', 'period-myths', 1, 'Being on your period means you’re ill.', 'myth', 'Is a period an illness?', 'Nope! A period is a normal, healthy part of the cycle. You might feel tired or crampy, but you’re not ill.', 'Lots of people sit exams, play sport and go to work on their period.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-06', 'period-myths', 1, 'Eating spicy food makes your period come early.', 'myth', 'Can a curry change your hormones?', 'Nope! There’s no good evidence that spicy food changes when your period arrives. Your hormones set the timing.', 'Stress, illness and travel are much more likely to shift your period.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-07', 'period-myths', 1, 'You should stay in bed when you’re on your period.', 'myth', 'Does rest always help cramps?', 'Nope! Unless you feel unwell, you can carry on as normal. Gentle movement can even ease cramps.', 'Plenty of top athletes have competed on their period.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-08', 'period-myths', 1, 'Cold drinks make period pain worse.', 'myth', 'Is there any evidence?', 'Myth. There’s no good evidence cold food or drinks cause period pain. Warm drinks might just feel cosy.', 'A warm drink and a hot water bottle are simple, soothing extras when cramps hit.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-09', 'period-myths', 1, 'Everyone can tell when you’re on your period.', 'myth', 'Can you tell when your friends are?', 'Nope! Unless you tell them, people really can’t tell. Period products are made to be invisible.', 'Plenty of athletes compete on their period and nobody knows.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-1-10', 'period-myths', 1, 'Period blood attracts sharks, so you can’t swim in the sea.', 'myth', 'Ask the people who study shark bites.', 'Myth! Shark researchers have found no evidence that people on their period are at higher risk. Sea swims are fine.', 'Water pressure means very little period blood leaves your body while you swim anyway.', 'Florida Museum: International Shark Attack File', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-01', 'period-myths', 2, 'Pain so bad you miss school or work is just part of having periods.', 'myth', 'Pain that stops your day matters.', 'Myth. Very painful periods can have treatable causes, like endometriosis. It’s worth seeing a doctor.', 'Endometriosis affects around 1 in 10 women.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-02', 'period-myths', 2, 'A hot water bottle on your tummy is a legit cramp hack.', 'fact', 'Warmth relaxes muscles.', 'True! Heat on your tummy or back helps the muscles relax.', 'A warm bath works for the same reason: heat helps muscles relax.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-03', 'period-myths', 2, 'Cramps happen because your womb is literally squeezing.', 'fact', 'Your womb is a muscle.', 'True. Chemicals called prostaglandins make the womb tighten to shed its lining, and that squeeze is what you feel.', 'The same chemicals can upset your tummy too, which is why loose poos on your period are common.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-04', 'period-myths', 2, 'Ibuprofen can help cramps, but it isn’t right for everyone.', 'fact', 'Always check the label.', 'True. It often helps, but if you have asthma or stomach problems, ask a pharmacist first.', 'Paracetamol is another option if ibuprofen isn’t right for you.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-05', 'period-myths', 2, 'Literally everyone gets period pain.', 'myth', 'Are all bodies the same?', 'Myth. Lots of people get cramps, but not everyone does, and how strong they feel varies a lot.', 'How much pain you feel can change over the years.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-06', 'period-myths', 2, 'Cramps that get worse every year are just normal.', 'myth', 'Changes are worth noticing.', 'Myth. Pain that gets worse over time can be a sign of a condition like endometriosis and should be checked.', 'Logging your pain in Spot it can help a doctor spot patterns.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-07', 'period-myths', 2, 'A gentle stretch or a short walk can ease cramps.', 'fact', 'Movement gets things flowing.', 'True. Light activity can ease cramps and lift your mood with feel-good endorphins.', 'Child’s pose is a popular gentle stretch for cramps.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-08', 'period-myths', 2, 'Bad period pain means you’ll struggle to get pregnant one day.', 'myth', 'Pain and fertility are different things.', 'Myth. Most period pain isn’t linked to fertility problems. If pain is severe, a doctor can check for causes.', 'For many people, period pain gets easier with age.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-09', 'period-myths', 2, 'Period pain can spread to your lower back and thighs.', 'fact', 'Is it always just your tummy?', 'Yep! Cramps often spread to your back and the tops of your legs. A heat pad on your back can help too.', 'Some people get a dull ache before their period even starts.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-myths-2-10', 'period-myths', 2, 'Painkillers work best if you wait until cramps are at their worst.', 'myth', 'Is it easier to stop a fire early or late?', 'Nope! Anti-inflammatory painkillers like ibuprofen tend to work better when taken as soon as the pain starts. Always check the label first.', 'They work by calming down the chemicals that cause cramps.', 'ACOG: Dysmenorrhea', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-01', 'period-myths', 3, 'It’s fine to leave a tampon in all day and all night.', 'myth', 'How often should it change?', 'Myth. Change tampons every 4 to 8 hours to keep the small risk of toxic shock syndrome low.', 'Toxic shock syndrome is very rare, but knowing the signs is smart.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-02', 'period-myths', 3, 'Menstrual cups are only for adults.', 'myth', 'Cups come in different sizes.', 'Myth! Cups come in smaller sizes, and teens can use them once they feel comfortable.', 'Cups can hold more than a tampon, so some people change them less often.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-03', 'period-myths', 3, 'Even on light days, pads should be changed every few hours.', 'fact', 'Freshness matters.', 'True. Changing about every 3 to 4 hours keeps you comfy and helps prevent smells and irritation.', 'Pads with wings help stop them shifting around.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-04', 'period-myths', 3, 'Toxic shock syndrome only ever comes from tampons.', 'myth', 'Think about other products and causes.', 'Myth. It’s rare, and it’s been linked to tampons and cups, but it can happen for other reasons too.', 'Toxic shock syndrome is caused by toxins released by certain bacteria.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-05', 'period-myths', 3, 'Scented wipes and douches keep your vagina extra clean.', 'myth', 'The vagina is a self-cleaning oven.', 'Myth. The vagina cleans itself. Scented products can upset its balance. Plain water on the outside is plenty.', 'A healthy vagina is slightly acidic, which helps keep bad bacteria away.', 'NHS: Vaginal discharge', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-06', 'period-myths', 3, 'Period pants can be washed and worn again and again.', 'fact', 'Think reusable.', 'True! Rinse them in cold water, then wash them as the label says.', 'Period pants come in different absorbencies, just like pads.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-07', 'period-myths', 3, 'You have to take your menstrual cup out to pee.', 'myth', 'Where is the cup sitting?', 'Myth! The cup sits in the vagina, and pee comes out of a separate opening, so you can go as normal.', 'Pee comes out of the urethra, a tiny separate opening just above the vagina.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-08', 'period-myths', 3, 'A tampon can get lost somewhere inside your body.', 'myth', 'Where does the vagina lead?', 'Myth. The opening of the cervix is far too small for a tampon to get through, so it can’t get lost.', 'If a tampon string tucks up out of sight, you can usually still reach it with clean fingers.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-09', 'period-myths', 3, 'You have to throw away a menstrual cup after every period.', 'myth', 'Think ‘reusable’.', 'Nope! With proper cleaning, a menstrual cup can last for years.', 'One cup can replace thousands of pads or tampons over its life.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-3-10', 'period-myths', 3, 'Flushing pads or tampons down the toilet can block pipes.', 'fact', 'Where does it all end up?', 'True! Pads and tampons don’t break down in water. Wrap them up and pop them in the bin.', 'Blocked sewers are often full of things that should have gone in the bin.', 'Water UK: Bin it, don’t block it', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-01', 'period-myths', 4, 'In some places, girls miss school because they don’t have period products or safe toilets.', 'fact', 'Is this just a far-away problem?', 'Correct! Period poverty affects girls worldwide, including in wealthy countries.', 'Free period product schemes now run in many schools.', 'UNICEF: Menstrual hygiene', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-02', 'period-myths', 4, 'Using a tampon or cup stretches your vagina permanently.', 'myth', 'How stretchy is the vagina?', 'Not true! The vagina is very elastic and returns to its usual shape.', 'The vaginal walls have folds called rugae that let it stretch and recover.', 'Cleveland Clinic: Vagina', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-03', 'period-myths', 4, 'The word ‘hysteria’ comes from the Greek word for womb.', 'fact', 'Hyster-ectomy?', 'Correct! It comes from ‘hystera’, meaning womb. Ancient doctors wrongly blamed many illnesses on the womb.', 'It’s a reminder of how old some period myths are.', 'Merriam-Webster: Hysteria', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-04', 'period-myths', 4, 'Toxic shock syndrome is so common that most tampon users will get it.', 'myth', 'How rare is rare?', 'Not true! TSS is very rare. Using the lowest absorbency you need and changing regularly keeps the risk low.', 'Most tampon users will never meet TSS.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-05', 'period-myths', 4, 'Period pain without an underlying condition usually starts within a year or two of a first period.', 'fact', 'When does it begin?', 'Correct! This is called primary dysmenorrhoea. It often starts once periods become regular.', 'Pain that starts later in life is more likely to have another cause.', 'ACOG: Dysmenorrhea', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-06', 'period-myths', 4, 'Period blood comes from the ovaries.', 'myth', 'What gets shed each month?', 'Not true! Period blood comes from the lining of the womb, which leaves the body through the cervix and vagina. The ovaries release eggs.', 'The womb is about the size of a small pear.', 'Cleveland Clinic: Menstruation', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-07', 'period-myths', 4, 'Menstrual fluid isn’t all blood. It also contains womb lining, mucus and other fluid.', 'fact', 'What’s being shed?', 'Correct! Period fluid is a mix of blood, tissue from the womb lining and mucus.', 'That’s why it can look thicker than ordinary blood.', 'Cleveland Clinic: Menstruation', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-08', 'period-myths', 4, 'Missing a period always means something is wrong.', 'myth', 'What else can delay a period?', 'Not always! Stress, illness, travel, weight changes and being in your first years of periods can all delay one. Missing 3 or more is worth checking.', 'Spot it can show if a period is late compared to your usual.', 'NHS: Stopped or missed periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-09', 'period-myths', 4, 'Lots of intense training without eating enough can make periods stop.', 'fact', 'Energy in, energy out.', 'Correct! When the body doesn’t have enough energy, it can switch off periods to save fuel. This can weaken bones.', 'Doctors call this RED-S, relative energy deficiency in sport.', 'NHS: Stopped or missed periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-4-10', 'period-myths', 4, 'PMS was first described in the 1990s.', 'myth', 'Older than your parents?', 'Way earlier! A doctor described ‘premenstrual tension’ in 1931, and people noticed it long before then.', 'Ancient Greek writers described symptoms before periods too.', 'Frank, Archives of Neurology and Psychiatry (1931)', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-01', 'period-myths', 5, 'Big studies using app data have found no good evidence that periods sync up.', 'fact', 'Data vs stories.', 'Correct! Studies of people living together found cycles don’t sync. Apparent syncing is usually coincidence.', 'With cycles of different lengths, overlaps happen by chance.', 'Yang and Schank, Human Nature (2006)', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-02', 'period-myths', 5, 'Menstrual cups were invented in the 2000s.', 'myth', 'Older than you think.', 'Way older! Menstrual cups were patented in the 1930s.', 'Leona Chalmers patented an early cup in 1937.', 'Smithsonian: History of menstrual products', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-03', 'period-myths', 5, 'Early disposable pads were inspired by bandage material used by nurses in the First World War.', 'fact', 'Hospital supply cupboard.', 'Correct! Nurses noticed how absorbent the wartime material was, and it led to one of the first commercial pads.', 'Before that, many people used washable cloth.', 'Smithsonian: History of menstrual products', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-04', 'period-myths', 5, 'TSS happens because the tampon material itself is poisonous.', 'myth', 'Who makes the toxin?', 'Not true! TSS is caused by toxins from certain bacteria, like Staphylococcus aureus. The tampon is not the poison.', 'TSS can also happen after skin wounds or burns.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-05', 'period-myths', 5, 'Toxic shock syndrome can also happen with menstrual cups, though it’s very rare.', 'fact', 'Is any internal product zero risk?', 'Correct! TSS is extremely rare with cups, but cases have been reported. Clean and empty your cup as directed.', 'Washing hands before inserting helps.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-06', 'period-myths', 5, 'Doctors have long used 80 ml per period as the cut-off for ‘heavy’.', 'fact', 'Measured in millilitres.', 'Correct! Over 80 ml was the classic definition. Today doctors focus more on how much periods affect your life.', 'A typical period loses about 30 to 40 ml.', 'NHS: Heavy periods', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-07', 'period-myths', 5, 'Dark or brown period blood means it’s toxic.', 'myth', 'What does oxygen do to blood?', 'Not true! Darker blood is just older blood that has met more oxygen. It’s usually normal.', 'Brown is common at the start and end of a period.', 'Cleveland Clinic: Period blood colour', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-08', 'period-myths', 5, 'Scotland was the first country in the world to pass a law making period products free for anyone who needs them.', 'fact', 'A world first.', 'Correct! Scotland passed the Period Products Act in 2020.', 'Products are free in places like schools, colleges and community centres.', 'Scottish Government: Period Products Act', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-09', 'period-myths', 5, 'Over a lifetime, the average person has around 400 to 500 periods.', 'fact', 'Do the maths.', 'Correct! With periods from the early teens to the early fifties, it adds up to around 400 to 500.', 'That’s years of periods, which is why comfortable products matter.', 'ACOG: Your menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('period-myths-5-10', 'period-myths', 5, 'Cramps are caused by the womb lining tearing off the womb wall.', 'myth', 'Squeeze or tear?', 'Not quite! Cramps come from the womb muscle contracting, driven by prostaglandins. The lining sheds gently.', 'Strong contractions can briefly reduce blood flow, which adds to the ache.', 'ACOG: Dysmenorrhea', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-01', 'body-changes', 1, 'Puberty can start any time from about age 8 to 13.', 'fact', 'There’s a big range.', 'True. Starting earlier or later than your friends is completely normal.', 'Puberty usually takes several years from start to finish.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-02', 'body-changes', 1, 'Small lumps under the nipples are often the very first sign of puberty.', 'fact', 'What changes first?', 'True! They’re called breast buds, and they’re often the first sign things are starting.', 'It’s normal for one breast bud to appear before the other.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-03', 'body-changes', 1, 'Periods usually arrive before any other puberty changes.', 'myth', 'Periods tend to come a bit later.', 'Myth. Periods usually start about two years after breasts begin to develop.', 'The average age for a first period is around 12.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-04', 'body-changes', 1, 'You can shoot up several centimetres in a single year during puberty.', 'fact', 'Ever outgrown jeans fast?', 'True. Growth spurts are a big part of puberty.', 'Hands and feet often grow first, before the rest of you catches up.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-05', 'body-changes', 1, 'Everyone in your class will go through puberty at the same time.', 'myth', 'Look around the room.', 'Myth. Puberty starts and moves at different speeds for everyone, and that’s fine.', 'Some people start puberty in primary school, others at secondary. Both are normal.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-06', 'body-changes', 1, 'Puberty is kicked off by messages from your brain.', 'fact', 'The control centre is in your head.', 'True. Your brain sends hormones that tell your ovaries to start making oestrogen, and puberty begins.', 'The part of your brain that kicks off puberty is about the size of an almond.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-07', 'body-changes', 1, 'Getting sweatier during puberty is totally normal.', 'fact', 'Your sweat glands are growing up too.', 'True. Sweat glands get more active. A daily wash and deodorant help.', 'Sweat itself doesn’t smell. Bacteria on your skin cause the smell.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-08', 'body-changes', 1, 'Mood swings during puberty mean something is wrong with you.', 'myth', 'Hormones and growing up both play a part.', 'Myth. Changing hormones and new experiences can make moods go up and down. If you feel low a lot, talk to someone.', 'Talking to someone you trust really can make big feelings easier.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-09', 'body-changes', 1, 'Feeling more self-conscious about your body during puberty is really common.', 'fact', 'Are you the only one?', 'Yep! Your body is changing fast, so it makes sense to notice it more. Everyone around you is going through it too.', 'Talking to a trusted adult or friend can make it feel lighter.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-1-10', 'body-changes', 1, 'Girls and boys start puberty at exactly the same age.', 'myth', 'Look around your class.', 'Nope! Girls usually start puberty a year or two earlier than boys.', 'That’s why girls are often taller than boys for a while.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-01', 'body-changes', 2, 'It’s really common for one breast to be a bit bigger than the other.', 'fact', 'Bodies are rarely perfectly even.', 'True! Breasts often grow at different speeds, and a small difference is very common.', 'Most adult women have breasts that are slightly different sizes.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-02', 'body-changes', 2, 'Stretch marks from growing fast are bad for you.', 'myth', 'They’re a sign of growth.', 'Myth. Stretch marks are common when you grow quickly. They’re harmless and often fade.', 'Stretch marks are very common. Most people have some.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-03', 'body-changes', 2, 'New hair under your arms and around your private parts is part of puberty.', 'fact', 'Hormones switch on new hair growth.', 'True. Whether you remove it or keep it is totally your choice.', 'Body hair often starts thin and light, then gets thicker over time.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-04', 'body-changes', 2, 'Putting on some weight during puberty is a normal part of growing.', 'fact', 'Your body is building.', 'True. Hips widen and your body stores a little more fat. That’s healthy and expected.', 'Your body needs some fat to start and keep regular periods.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-05', 'body-changes', 2, 'Growing breasts can feel sore or tender.', 'fact', 'Growing tissue can ache.', 'True. Tenderness often comes and goes while breasts develop.', 'Breast tenderness can also come and go with your cycle later on.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-06', 'body-changes', 2, 'Shaving makes hair grow back thicker and darker.', 'myth', 'Does the root change?', 'Myth. Shaving cuts hair at the surface. Regrowth can feel stubbly, but it isn’t thicker or darker.', 'Regrowth feels stubbly because shaving cuts each hair at a blunt angle.', 'Mayo Clinic: Hair removal myths', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-07', 'body-changes', 2, 'Wearing a bra makes your breasts grow faster.', 'myth', 'What really controls breast growth?', 'Myth. Hormones drive breast growth. Bras are just for comfort and support.', 'A bra that fits well makes a big difference to comfort.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-08', 'body-changes', 2, 'Growth usually slows down a year or two after your first period.', 'fact', 'The big spurt tends to come first.', 'True. The biggest growth spurt usually happens before your first period.', 'After periods start, most girls grow a few more centimetres.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-09', 'body-changes', 2, 'Your hands and feet can grow before the rest of you during puberty.', 'fact', 'Ever needed new shoes before new trousers?', 'Yep! Hands and feet often grow first, so it’s normal to feel a bit out of proportion for a while.', 'Your arms and legs usually catch up next, then your body.', 'Nemours KidsHealth: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-2-10', 'body-changes', 2, 'Breasts stop growing the moment your first period arrives.', 'myth', 'Does everything change on one day?', 'Nope! Breasts usually keep developing for a few years after periods start.', 'Breast development often finishes in your late teens.', 'Nemours KidsHealth: Breasts and bras', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-01', 'body-changes', 3, 'Discharge in your underwear is your vagina doing its job.', 'fact', 'It has a purpose.', 'True! Discharge keeps the vagina clean, moist and protected from infection.', 'The vagina has its own good bacteria that help keep it healthy.', 'NHS: Vaginal discharge', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-02', 'body-changes', 3, 'Discharge can show up months before your very first period.', 'fact', 'It can be an early sign.', 'True. Many girls notice it a few months to a year before their first period.', 'A panty liner can help if discharge bothers you.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-03', 'body-changes', 3, 'Healthy discharge should have zero smell.', 'myth', 'A mild smell can be normal.', 'Myth. A mild smell is normal. A strong, fishy or unusual smell is worth checking.', 'Discharge can smell a little different at different points in your cycle.', 'NHS: Vaginal discharge', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-04', 'body-changes', 3, 'Discharge changes during your cycle.', 'fact', 'Hormones change it.', 'True. It can be thicker or thinner, cloudier or clearer at different times of the month.', 'Changes in discharge can be a handy clue to where you are in your cycle.', 'NHS: Vaginal discharge', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-05', 'body-changes', 3, 'Thick, white discharge with itching can be a sign of thrush.', 'fact', 'Think cottage cheese.', 'True. Thrush is a common yeast infection. A pharmacist can help you sort it.', 'Thrush isn’t a sexually transmitted infection.', 'NHS: Thrush', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-06', 'body-changes', 3, 'You should wash inside your vagina with soap.', 'myth', 'It cleans itself.', 'Myth. Soap inside can cause irritation. Gently washing the outside with water or a mild unscented wash is enough.', 'A healthy vagina is slightly acidic, and soap can upset that balance.', 'NHS: Vaginal discharge', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-07', 'body-changes', 3, 'Green, grey or yellow discharge with a strong smell is worth showing a doctor.', 'fact', 'Colour can be a clue.', 'True. These can be signs of an infection, which is usually easy to treat.', 'Most vaginal infections are easy to treat once they’re checked.', 'NHS: Vaginal discharge', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-08', 'body-changes', 3, 'Cotton underwear can help keep things comfy down there.', 'fact', 'Breathable fabrics help.', 'True. Cotton lets air through and can help prevent irritation and thrush.', 'Changing out of damp swimwear or gym kit quickly can help prevent thrush.', 'NHS: Thrush', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-09', 'body-changes', 3, 'Dried discharge can leave a yellowish mark on your underwear, and that’s normal.', 'fact', 'What colour does clear liquid leave when it dries?', 'Yep! Healthy discharge is clear or white, but it can dry a little yellow on fabric.', 'Discharge naturally keeps your vagina clean and healthy.', 'NHS: Vaginal discharge', 'approved', 'Spot it content team', true, now()),
  ('body-changes-3-10', 'body-changes', 3, 'Tight leggings and jeans always cause infections.', 'myth', 'Is it ‘always’ or ‘sometimes for some people’?', 'Not always! Tight clothes don’t cause infections on their own. If you get thrush a lot, loose cotton underwear can help.', 'Changing out of sweaty gym kit soon after exercise helps too.', 'NHS: Thrush', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-01', 'body-changes', 4, 'Thelarche is the medical name for the start of breast development.', 'fact', 'Greek words again.', 'Correct! Thelarche is usually the first visible sign of puberty in girls.', '‘Thele’ is Greek for nipple.', 'Nemours KidsHealth: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-02', 'body-changes', 4, 'First periods usually arrive about 2 to 3 years after breasts start developing.', 'fact', 'Think timeline.', 'Correct! Breast buds usually come first, and menarche follows a couple of years later.', 'That’s why breast buds are a good early clue.', 'ACOG: Menstruation in girls and adolescents', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-03', 'body-changes', 4, 'In girls, the fastest growth spurt usually happens after the first period.', 'myth', 'Before or after?', 'Not true! The peak growth spurt usually comes before the first period. Growth slows afterwards.', 'Most girls grow only a few more centimetres after periods start.', 'Nemours KidsHealth: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-04', 'body-changes', 4, 'Growth plates at the ends of long bones close after puberty, and that’s when you stop getting taller.', 'fact', 'Bones have a finish line.', 'Correct! Once growth plates fuse, bones can’t get any longer.', 'X-rays can show whether growth plates are still open.', 'Nemours KidsHealth: Growth plates', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-05', 'body-changes', 4, 'Oestrogen has nothing to do with when you stop growing.', 'myth', 'Which hormone closes growth plates?', 'Not true! Oestrogen is the main hormone that closes growth plates, in boys too.', 'That’s why earlier puberty can mean a shorter final height.', 'Endocrine Society: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-06', 'body-changes', 4, 'Signs of puberty before age 8 in girls should be checked by a doctor.', 'fact', 'Too early?', 'Correct! This is called early, or precocious, puberty, and doctors can check what’s causing it.', 'Treatment can pause puberty if needed.', 'NHS: Early or delayed puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-07', 'body-changes', 4, 'No breast development by 13 means you’re just a late bloomer, and nothing needs checking.', 'myth', 'When should a doctor take a look?', 'Not quite! If there are no signs of puberty by 13, it’s worth seeing a doctor. Usually all is fine, but it’s good to check.', 'Late puberty often runs in families.', 'NHS: Early or delayed puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-08', 'body-changes', 4, 'Doctors use ‘Tanner stages’, from 1 to 5, to describe how far along puberty is.', 'fact', 'Five steps.', 'Correct! Tanner stages track breast and pubic hair development from childhood to adult.', 'They’re named after the British doctor James Tanner.', 'Nemours KidsHealth: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-09', 'body-changes', 4, 'The average age for a first period in the UK and US is about 15.', 'myth', 'Earlier or later?', 'Earlier! The average is around 12, with anything from about 9 to 15 being common.', 'Some start at 8 and some at 16.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('body-changes-4-10', 'body-changes', 4, 'Pubic and underarm hair are mainly caused by androgens from the adrenal glands.', 'fact', 'Glands above the kidneys.', 'Correct! The adrenal glands release androgens that kick-start body hair and body odour.', 'This stage is called adrenarche.', 'Endocrine Society: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-01', 'body-changes', 5, 'Puberty is switched on when the brain starts releasing a hormone called GnRH in pulses.', 'fact', 'Pulse, not steady flow.', 'Correct! Pulses of GnRH tell the pituitary to release LH and FSH, which wake up the ovaries.', 'A steady flow of GnRH would actually switch the system off.', 'Endocrine Society: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-02', 'body-changes', 5, 'Puberty starts in the ovaries, which then tell the brain what to do.', 'myth', 'Who’s the boss?', 'Backwards! Puberty starts in the brain, which signals the pituitary, which signals the ovaries.', 'This chain is called the HPO axis.', 'Endocrine Society: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-03', 'body-changes', 5, 'Leptin, a hormone made by body fat, helps tell the brain there’s enough energy for puberty.', 'fact', 'Fuel gauge.', 'Correct! Leptin acts like a fuel gauge, which is one reason very low body fat can delay periods.', 'Leptin also helps control appetite.', 'Endocrine Society: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-04', 'body-changes', 5, 'The average age of first periods has gone up over the last 150 years.', 'myth', 'Better food, earlier puberty?', 'Not true! It has dropped, mostly thanks to better nutrition and health.', 'In the 1800s, first periods often came at 16 or 17.', 'ACOG: Menstruation in girls and adolescents', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-05', 'body-changes', 5, 'Adrenarche, when the adrenal glands start making more androgens, can begin around age 6 to 8.', 'fact', 'Earlier than breasts.', 'Correct! It often starts years before breast development, though it’s not visible at first.', 'It’s behind the first body odour.', 'Endocrine Society: Puberty', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-06', 'body-changes', 5, 'Healthy vaginal fluid is slightly alkaline, like soap.', 'myth', 'Acid or alkali?', 'Not true! A healthy vagina is acidic, usually around pH 3.8 to 4.5. That helps keep infections away.', 'That’s one reason soap inside the vagina is a bad idea.', 'Cleveland Clinic: Vaginal pH', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-07', 'body-changes', 5, 'Good bacteria called lactobacilli help keep the vagina acidic and healthy.', 'fact', 'Friendly bugs.', 'Correct! Lactobacilli make lactic acid, which keeps the pH low and harmful bugs away.', 'They’re related to the bacteria in yoghurt.', 'Cleveland Clinic: Vaginal pH', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-08', 'body-changes', 5, 'The teenage brain finishes developing by about 16.', 'myth', 'Longer than you think.', 'Not true! The brain keeps developing into the mid-twenties, especially the areas for planning and decisions.', 'The front of the brain is the last to finish.', 'NIMH: The teen brain', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-09', 'body-changes', 5, 'Most of your adult bone mass is built by your late teens.', 'fact', 'Bone bank.', 'Correct! About 90% of peak bone mass is built by around age 18 to 20, so the teen years matter.', 'Calcium, vitamin D and exercise all help.', 'NIH: Kids and their bones', 'approved', 'Spot it content team', true, now()),
  ('body-changes-5-10', 'body-changes', 5, 'Stretch marks happen because skin cells die.', 'myth', 'What stretches?', 'Not quite! Stretch marks form when the deeper layer of skin stretches quickly and its collagen and elastic fibres tear.', 'They often fade to silver or pale over time.', 'NHS: Stretch marks', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-01', 'period-care', 1, 'Pads come in different sizes for light days and heavy days.', 'fact', 'One size doesn’t fit every day.', 'True! A lighter pad on light days and a bigger one on heavy days keeps you comfy.', 'Night-time pads are longer to help stop leaks while you sleep.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-02', 'period-care', 1, 'The most absorbent tampon is always the safest pick.', 'myth', 'More isn’t always better.', 'Myth. Use the lowest absorbency that works for your flow. It lowers the risk of toxic shock syndrome.', 'Tampon boxes show absorbency with little drop symbols.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-03', 'period-care', 1, 'Many menstrual cups can stay in for up to 12 hours.', 'fact', 'Cups collect rather than soak up.', 'True for many cups, but always check the instructions for yours.', 'Most cups are made from medical-grade silicone.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-04', 'period-care', 1, 'Reusable cloth pads are one-and-done.', 'myth', 'Think reusable.', 'Myth! Cloth pads are rinsed, washed and dried, then used again for months or even years.', 'Some cloth pads can be used for several years.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-05', 'period-care', 1, 'You can sleep with a tampon in if you change it within 8 hours.', 'fact', 'Timing is everything.', 'True. Pop a fresh one in before bed and take it out within 8 hours.', 'Period pants or a pad are good options if you sleep longer than 8 hours.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-06', 'period-care', 1, 'Menstrual cups need a proper clean between periods.', 'fact', 'Follow the care steps.', 'True. Most cups are boiled or sterilised between periods. Check your cup’s instructions.', 'With good care, many cups last for years.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-07', 'period-care', 1, 'You have to be a grown-up to use tampons.', 'myth', 'When can you start?', 'Myth! Anyone with periods can use tampons, even from their first period, once they feel ready.', 'Slim or ‘light’ tampons can be easier to start with.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-08', 'period-care', 1, 'The bathroom shelf is the perfect place to keep spare tampons.', 'myth', 'Think about all that steam.', 'Myth. Keep period products somewhere clean and dry so they stay hygienic until you use them.', 'Steam can make packaging damp, so a drawer or bag is a better home.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-09', 'period-care', 1, 'Period pants can be worn on their own or as a back-up with a tampon or cup.', 'fact', 'Can they team up?', 'Yep! Use them alone on lighter days or as leak back-up on heavier ones.', 'Some period pants hold as much as a few tampons.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-1-10', 'period-care', 1, 'Panty liners are made for heavy-flow days.', 'myth', 'Think about how thin they are.', 'Nope! Liners are very thin and are for discharge or the very lightest days. On heavier days you’ll need a pad, tampon, cup or period pants.', 'Liners are great for the last day of your period.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-01', 'period-care', 2, 'Tracking your period means fewer surprise moments.', 'fact', 'That’s what Spot it is for!', 'True. Knowing roughly when it’s due means you can pack products and plan ahead.', 'Spot it uses the periods you log to predict your next one.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-02', 'period-care', 2, 'A good night’s sleep can make PMS easier to handle.', 'fact', 'Rest changes how you feel.', 'True. Poor sleep can make tiredness and low mood feel worse.', 'A regular bedtime helps, even at weekends.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-03', 'period-care', 2, 'Sleep makes zero difference to how you feel before your period.', 'myth', 'Think about tired days.', 'Myth. Sleep affects mood and energy, so getting enough can make PMS easier.', 'Being tired can make cramps feel worse too.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-04', 'period-care', 2, 'Keeping a spare pad or tampon in your bag is a smart move.', 'fact', 'Periods don’t always RSVP.', 'True. Periods don’t always arrive on time, so a spare saves stress.', 'A small pouch in your bag keeps spares tidy and private.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-05', 'period-care', 2, 'Leaks mean you’re doing it wrong.', 'myth', 'Leaks happen to everyone.', 'Myth! Leaks are really common, especially on heavy days or overnight. Trying a different size or product can help.', 'On heavy days, a pad as backup with a tampon or cup can help.', 'NHS: Periods – sanitary products', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-06', 'period-care', 2, 'Hot water is best for getting period stains out.', 'myth', 'Heat can make it worse.', 'Myth. Use cold water as soon as you can. Hot water can set blood stains.', NULL, NULL, 'approved', 'Spot it content team', true, now()),
  ('period-care-2-07', 'period-care', 2, 'You should skip all exercise on heavy days.', 'myth', 'Listen to your body.', 'Myth. You can move on any day of your period, and gentle exercise may even help.', 'Some people feel extra energetic in the days after their period ends.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-08', 'period-care', 2, 'Slow breathing or yoga can take the edge off PMS.', 'fact', 'Calm body, calm mind.', 'True. Things that lower stress can ease PMS for lots of people.', 'Even five slow breaths can help you feel calmer.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-09', 'period-care', 2, 'Counting how many pads or tampons you use a day can help a doctor tell if your periods are heavy.', 'fact', 'What do doctors like to measure?', 'Yep! Jotting down how often you change helps a doctor understand your flow.', 'You can add notes like this in your Spot it log.', 'NHS: Heavy periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-2-10', 'period-care', 2, 'It’s fine to use a tampon to soak up discharge between periods.', 'myth', 'What are tampons designed for?', 'Nope! Tampons are for periods only. Using them when you’re not bleeding can dry you out and raise the small risk of toxic shock syndrome.', 'A liner is the better choice for discharge.', 'FDA: The facts on tampons', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-01', 'period-care', 3, 'Needing a fresh pad or tampon every hour or two can mean your periods are heavy.', 'fact', 'How fast is it filling?', 'True. Soaking through that fast, or bleeding through clothes, is worth checking with a doctor.', 'Heavy periods affect a lot of people, and help is available.', 'NHS: Heavy periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-02', 'period-care', 3, 'No period for 3 months or more? Worth a doctor’s visit.', 'fact', 'Missing several is different from missing one.', 'True. There are lots of possible reasons, and a doctor can help find out why.', 'Stress, weight changes and lots of exercise are common reasons for missed periods.', 'NHS: Stopped or missed periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-03', 'period-care', 3, 'Feeling wiped out or dizzy with heavy periods can mean low iron.', 'fact', 'Blood carries iron.', 'True. Losing a lot of blood can lower iron. A simple blood test can check.', 'Low iron is one of the most common nutrition problems in the world.', 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-04', 'period-care', 3, 'If your first period hasn’t come by 16, you should just keep waiting.', 'myth', 'There’s a usual age range.', 'Myth. Most people start by 16. If not, it’s worth a doctor’s check to see everything is on track.', 'Most people get their first period between the ages of 10 and 16.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-05', 'period-care', 3, 'Period pain that painkillers can’t touch should be checked out.', 'fact', 'Pain should be manageable.', 'True. Pain that stops normal life or doesn’t ease with usual treatments can have a treatable cause.', 'Endometriosis can take years to diagnose, so speaking up matters.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-06', 'period-care', 3, 'Heavy periods run in my family, so mine are nothing to worry about.', 'myth', 'Families can share conditions too.', 'Myth. Heavy periods can run in families, but they can still have treatable causes. Get them checked.', 'Noting how heavy your periods are helps a doctor understand them.', 'NHS: Heavy periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-07', 'period-care', 3, 'Doctors are used to talking about periods, even if it feels awkward.', 'fact', 'They hear this every day.', 'True. Period problems are super common, and doctors and nurses talk about them all the time.', 'A nurse or pharmacist can be a great first person to ask.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-08', 'period-care', 3, 'A sudden high fever, a rash and feeling really unwell while using a tampon is an emergency.', 'fact', 'These are warning signs.', 'True. They can be signs of toxic shock syndrome, which is rare but serious. Take the tampon out and get urgent help.', NULL, 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-09', 'period-care', 3, 'A period that lasts more than 7 days is worth mentioning to a doctor.', 'fact', 'What’s the usual range?', 'Yep! Periods usually last 2 to 7 days. Longer ones can be checked to make sure everything is OK.', 'Long periods can be a reason for low iron.', 'NHS: Heavy periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-3-10', 'period-care', 3, 'Bleeding between periods every month is nothing to bother a doctor about.', 'myth', 'Is a regular surprise still a surprise?', 'Nope! Light spotting now and then can be normal, but regular bleeding between periods should be checked by a doctor.', 'Doctors hear about this a lot, so there’s no need to feel awkward.', 'NHS: Bleeding between periods', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-01', 'period-care', 4, 'Tampons are labelled by absorbency, and ‘light’ holds less than about 6 grams of fluid.', 'fact', 'Grams, not ml.', 'Correct! Standard labels go light, regular, super and super plus, each holding a bit more.', 'The labels are standard so you can compare brands.', 'FDA: The facts on tampons', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-02', 'period-care', 4, 'Menstrual cups hold less than a tampon.', 'myth', 'Compare a cup and a tampon.', 'Not true! Many cups hold about 20 to 30 ml, more than most tampons.', 'That’s why cups can often stay in longer.', 'Cleveland Clinic: Menstrual cups', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-03', 'period-care', 4, 'Early TSS can look like flu: high fever, being sick, a sunburn-like rash and dizziness.', 'fact', 'Sneaky symptoms.', 'Correct! If you have these while using a tampon or cup, remove it and get urgent help.', 'TSS is rare but serious, so act fast.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-04', 'period-care', 4, 'If you think you have TSS, keep the tampon in so the doctor can see it.', 'myth', 'Remove or keep?', 'Not true! Take it out straight away and get urgent medical help. Tell the doctor you were using one.', 'Quick treatment makes a big difference.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-05', 'period-care', 4, 'Boiling a menstrual cup for a few minutes between periods is a common way to clean it.', 'fact', 'Hot water to the rescue.', 'Correct! Many brands suggest boiling between periods and rinsing in between changes. Always follow your cup’s instructions.', 'Some people use a separate pan just for the cup.', 'Cleveland Clinic: Menstrual cups', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-06', 'period-care', 4, 'Period pants need a hot wash with fabric softener to work properly.', 'myth', 'What does softener do to absorbent fabric?', 'Not true! Most brands say rinse in cold water, wash cool and skip softener, because it can block the absorbent layers.', 'Air-drying helps them last longer.', 'Which?: Period pants care', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-07', 'period-care', 4, 'Ibuprofen and naproxen ease cramps by lowering prostaglandins.', 'fact', 'Remember the squeeze chemicals?', 'Correct! These anti-inflammatories reduce the chemicals that make the womb contract.', 'They work best taken at the first sign of pain.', 'ACOG: Dysmenorrhea', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-08', 'period-care', 4, 'Paracetamol and ibuprofen work in exactly the same way.', 'myth', 'Same box, same job?', 'Not true! Ibuprofen is an anti-inflammatory that lowers prostaglandins. Paracetamol works differently and isn’t anti-inflammatory.', 'Always check doses and ask a pharmacist if unsure.', 'NHS: Ibuprofen', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-09', 'period-care', 4, 'Tranexamic acid is a non-hormonal medicine that can make heavy periods lighter.', 'fact', 'No hormones needed.', 'Correct! It helps blood clot in the womb, so less blood is lost. It’s only taken during your period.', 'It doesn’t help with pain, though.', 'NHS: Tranexamic acid', 'approved', 'Spot it content team', true, now()),
  ('period-care-4-10', 'period-care', 4, 'Iron tablets can turn your poo dark or black.', 'fact', 'A common side effect.', 'Correct! Dark poo is a common, harmless side effect of iron tablets. Some people also get an upset tummy.', 'Taking them with food can ease tummy upset, though a little less iron is absorbed.', 'NHS: Iron deficiency anaemia', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-01', 'period-care', 5, 'Tampons contain asbestos to make you bleed more.', 'myth', 'Classic internet rumour.', 'Not true! This myth has been around for years and has no basis. Tampons are regulated medical products.', 'In the US, the FDA regulates tampons as medical devices.', 'FDA: The facts on tampons', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-02', 'period-care', 5, 'Using the lowest-absorbency tampon you need lowers the risk of TSS.', 'fact', 'Less is more.', 'Correct! Higher absorbency is linked with higher TSS risk, so match the tampon to your flow.', 'Change at least every 4 to 8 hours.', 'NHS: Toxic shock syndrome', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-03', 'period-care', 5, 'Heavy periods are one of the most common causes of iron deficiency anaemia in young women.', 'fact', 'Where does iron go?', 'Correct! Losing more blood each month means losing more iron.', 'Signs include tiredness, breathlessness and pale skin.', 'NHS: Iron deficiency anaemia', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-04', 'period-care', 5, 'A ferritin blood test measures how much oxygen your blood carries.', 'myth', 'Ferr- means iron.', 'Not true! Ferritin shows how much iron your body has stored.', 'Low ferritin can show up before anaemia does.', 'NHS: Ferritin test', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-05', 'period-care', 5, 'You can have low iron stores even if your haemoglobin is normal.', 'fact', 'Two different tests.', 'Correct! Your iron stores can run low before your haemoglobin drops.', 'This is called iron deficiency without anaemia.', 'NIH Office of Dietary Supplements: Iron', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-06', 'period-care', 5, 'Bleeding disorders like von Willebrand disease are extremely rare in people with heavy periods.', 'myth', 'Doctors check for a reason.', 'Not true! A bleeding disorder is found in a fair number of people with heavy periods, so doctors may test for one.', 'Easy bruising and nosebleeds can be other clues.', 'ACOG: Von Willebrand disease', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-07', 'period-care', 5, 'Soaking through a pad or tampon every hour for several hours in a row needs urgent medical advice.', 'fact', 'How fast is too fast?', 'Correct! Very heavy bleeding like this, especially with dizziness, should be checked urgently.', 'Keep track of how often you change.', 'ACOG: Heavy menstrual bleeding', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-08', 'period-care', 5, 'Mefenamic acid, used for period pain, is a type of antibiotic.', 'myth', 'Same family as ibuprofen.', 'Not true! Mefenamic acid is an anti-inflammatory painkiller, like ibuprofen.', 'It can also make periods a bit lighter.', 'NHS: Mefenamic acid', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-09', 'period-care', 5, 'Menstrual discs sit higher up in the vagina than cups do.', 'fact', 'Disc vs cup.', 'Correct! Discs tuck up behind the pubic bone in the widest part of the vagina, while cups sit lower.', 'Discs are flatter and more flexible than cups.', 'Cleveland Clinic: Menstrual discs', 'approved', 'Spot it content team', true, now()),
  ('period-care-5-10', 'period-care', 5, 'Reusable pads should be soaked in bleach after every use.', 'myth', 'Gentle care.', 'Not true! Rinse in cold water, then wash as directed. Bleach can damage the fabric and irritate skin.', 'Drying them in sunlight can help lift stains.', 'Which?: Reusable pads care', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-01', 'hormones-101', 1, 'Hormones are tiny messengers that travel around your body in your blood.', 'fact', 'Think of a postal service.', 'True! They carry signals that tell different parts of your body what to do.', 'Your body makes more than 50 different hormones.', 'NHS: Endocrine system', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-02', 'hormones-101', 1, 'Your brain is the boss of your menstrual cycle.', 'fact', 'The cycle has a control centre.', 'True. Two spots in your brain send hormones that tell your ovaries what to do.', 'The pituitary gland, one of the bosses, is about the size of a pea.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-03', 'hormones-101', 1, 'Your ovaries are the only place that makes oestrogen.', 'myth', 'They have some helpers.', 'Myth. The ovaries make most of it, but fat tissue and the adrenal glands chip in too.', 'Because fat tissue makes oestrogen, body weight can affect periods.', 'NHS: Endocrine system', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-04', 'hormones-101', 1, 'Every month, your brain sends your ovaries a wake-up call.', 'fact', 'Think of a monthly alarm clock.', 'True. It’s a hormone called FSH. It nudges a few eggs to start growing, and usually just one makes it to the finish line.', 'FSH stands for follicle-stimulating hormone.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-05', 'hormones-101', 1, 'A sudden hormone rush is what tells an egg ‘go time!’', 'fact', 'Ovulation tests look for this.', 'True. It’s called the LH surge, and ovulation usually follows within a day or two.', 'LH stands for luteinising hormone.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-06', 'hormones-101', 1, 'Your hormones stay at the same level all month long.', 'myth', 'Think about the four seasons of your cycle.', 'Myth. Hormones rise and fall in a pattern, which is why you can feel different at different times.', 'Tracking how you feel can help you spot your own hormone patterns.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-07', 'hormones-101', 1, 'Female bodies make a little testosterone too.', 'fact', 'It isn’t only a ‘boy hormone’.', 'True. Small amounts come from the ovaries and adrenal glands.', 'Testosterone plays a part in bone and muscle strength in women too.', 'NHS: Endocrine system', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-08', 'hormones-101', 1, 'A gland in your neck can change your periods.', 'fact', 'It’s shaped like a butterfly.', 'True. If your thyroid is over- or underactive, periods can get heavier, lighter or irregular.', 'Your thyroid helps control how fast your body uses energy.', 'NHS: Underactive thyroid', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-09', 'hormones-101', 1, 'The pituitary gland, about the size of a pea, sits just below your brain.', 'fact', 'Small but mighty.', 'Yep! This tiny gland sends hormones that tell your ovaries what to do each month.', 'It’s sometimes called the ‘master gland’.', 'NHS: Pituitary gland', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-1-10', 'hormones-101', 1, 'Only women make oestrogen.', 'myth', 'Do hormones belong to one sex?', 'Nope! Men make some oestrogen too. It helps keep their bones healthy.', 'Women make some testosterone too, so it works both ways.', 'Cleveland Clinic: Estrogen', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-01', 'hormones-101', 2, 'Oestrogen is the builder that thickens your womb lining.', 'fact', 'It builds things up.', 'True. In the first half of your cycle, oestrogen builds the lining up.', 'The womb lining’s science name is the endometrium.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-02', 'hormones-101', 2, 'Progesterone keeps the womb lining cosy after ovulation.', 'fact', 'It holds things steady.', 'True. It keeps the lining ready, just in case an egg is fertilised.', 'Progesterone is the reason your temperature rises slightly after ovulation.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-03', 'hormones-101', 2, 'A drop in progesterone is the signal that starts your period.', 'fact', 'What happens when support disappears?', 'True. No pregnancy means progesterone falls, and the lining is shed as your period.', 'This drop is also linked to PMS symptoms.', 'NHS: Periods', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-04', 'hormones-101', 2, 'Oestrogen only matters for periods and babies.', 'myth', 'Think bones, skin and mood.', 'Myth! It also affects your bones, skin, heart and mood.', 'Oestrogen helps keep skin plump and moist.', 'NHS: Endocrine system', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-05', 'hormones-101', 2, 'Oestrogen helps keep your bones strong.', 'fact', 'Bones need hormones too.', 'True. It’s one reason bones can get weaker after menopause, when oestrogen drops.', 'Weight-bearing exercise like walking and dancing helps build strong bones too.', 'NHS: Osteoporosis', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-06', 'hormones-101', 2, 'Progesterone is at its highest during your period.', 'myth', 'When is it actually made?', 'Myth. It peaks after ovulation and drops just before your period.', NULL, 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-07', 'hormones-101', 2, 'Oestrogen hits its peak just before you ovulate.', 'fact', 'It helps trigger the big release.', 'True. It climbs through the first half of your cycle and peaks right before ovulation.', 'Some people feel more energetic around ovulation.', 'NHS: Fertility and your cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-08', 'hormones-101', 2, 'Oestrogen is the hormone behind breast growth in puberty.', 'fact', 'Which hormone starts the changes?', 'True. Rising oestrogen in puberty causes breast development and other body changes.', 'Oestrogen also helps change the shape of the hips during puberty.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-09', 'hormones-101', 2, 'Follicle-stimulating hormone (FSH) helps eggs grow in the ovaries.', 'fact', 'The clue is in the name.', 'Yep! FSH from the pituitary wakes up follicles, the little sacs that each hold an egg.', 'Each follicle is like a tiny bubble around an egg.', 'Cleveland Clinic: Follicle-stimulating hormone', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-2-10', 'hormones-101', 2, 'The hormone that triggers ovulation is insulin.', 'myth', 'Two letters, made by the pituitary.', 'Nope! It’s LH (luteinising hormone). A sudden surge of LH tells the ovary to release an egg.', 'Ovulation tests look for this LH surge in your pee.', 'Cleveland Clinic: Luteinizing hormone', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-01', 'hormones-101', 3, 'Your mood can change across your cycle, and hormones are part of the reason.', 'fact', 'Hormones reach your brain too.', 'True. Lots of people notice mood shifts at different points, especially before a period.', 'Logging moods in Spot it can show your own pattern over a few months.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-02', 'hormones-101', 3, 'PMS is all in your head.', 'myth', 'Is it real?', 'Myth. PMS is a real mix of physical and emotional symptoms linked to hormone changes.', 'Most women have PMS at some point in their lives.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-03', 'hormones-101', 3, 'Getting active can help with PMS.', 'fact', 'Movement and mood are linked.', 'True. Exercise can help mood, sleep and tiredness.', 'Even a short walk counts.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-04', 'hormones-101', 3, 'There’s a severe form of PMS called PMDD, and it can be treated.', 'fact', 'It’s more than a bad week.', 'True. PMDD causes very strong mood symptoms before periods. Doctors can help.', 'Treatments for PMDD can make a real difference.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-05', 'hormones-101', 3, 'Feeling low before your period means you have depression.', 'myth', 'Timing is the clue.', 'Myth. Low mood that comes before your period and lifts afterwards is usually linked to your cycle. If it hangs around, talk to a doctor.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-06', 'hormones-101', 3, 'Logging your moods can help a doctor understand your PMS.', 'fact', 'Patterns tell a story.', 'True. A couple of months of notes shows whether symptoms follow your cycle, and Spot it can help.', 'Two or three months of notes is usually enough to see a pattern.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-07', 'hormones-101', 3, 'Cutting back on caffeine might calm PMS a little.', 'fact', 'Think coffee, energy drinks and cola.', 'True. Caffeine can make anxiety, irritability and sleep problems worse for some people.', 'Caffeine is also in tea, chocolate and many fizzy drinks.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-08', 'hormones-101', 3, 'Hormones have nothing to do with how well you sleep.', 'myth', 'Think about the nights before a period.', 'Myth. Hormone changes before a period can make sleep harder for some people.', 'A cool, dark room can help you sleep better.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-09', 'hormones-101', 3, 'Many people feel hungrier in the week or so before their period.', 'fact', 'Snack o’clock?', 'Yep! Appetite changes are a common PMS symptom, and hormones play a part.', 'Your body uses a little more energy after ovulation.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-3-10', 'hormones-101', 3, 'Teen mood swings are caused only by hormones.', 'myth', 'What else is going on in a teen’s life?', 'Nope! Hormones play a part, but so do sleep, stress, school, friends and growing up. It’s a mix.', 'Sleep is one of the biggest mood boosters there is.', 'NHS: Stages of puberty', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-01', 'hormones-101', 4, 'The hypothalamus, pituitary and ovaries work together in a loop called the HPO axis.', 'fact', 'Three letters, one team.', 'Correct! The hypothalamus signals the pituitary, the pituitary signals the ovaries, and the ovaries signal back.', 'It’s like a group chat for your cycle.', 'Endocrine Society: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-02', 'hormones-101', 4, 'High oestrogen always tells the brain to make less LH.', 'myth', 'Is there a twist mid-cycle?', 'Not always! Usually oestrogen slows things down, but when it stays high just before ovulation it flips to ‘go’ and triggers the LH surge.', 'This flip is called positive feedback.', 'Endocrine Society: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-03', 'hormones-101', 4, 'Oestradiol is the main form of oestrogen before menopause.', 'fact', 'Oestrogen has a family.', 'Correct! There are several forms, and oestradiol is the strongest and most common in the reproductive years.', 'After menopause, a form called oestrone becomes the main one.', 'Cleveland Clinic: Estrogen', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-04', 'hormones-101', 4, 'Progesterone is mostly made by the brain.', 'myth', 'Remember the yellow body?', 'Not true! In the cycle, it’s mostly made by the corpus luteum in the ovary.', 'In pregnancy, the placenta takes over.', 'Cleveland Clinic: Progesterone', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-05', 'hormones-101', 4, 'Anti-Müllerian hormone (AMH) is made by small follicles in the ovaries.', 'fact', 'A follicle headcount.', 'Correct! AMH gives a rough idea of how many follicles are developing.', 'It doesn’t predict when someone can get pregnant.', 'Cleveland Clinic: AMH', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-06', 'hormones-101', 4, 'Women have about the same testosterone levels as men.', 'myth', 'How big is the gap?', 'Not true! Women usually have around a tenth to a twentieth of the testosterone men have.', 'It still matters for energy, mood and libido.', 'Cleveland Clinic: Testosterone', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-07', 'hormones-101', 4, 'High prolactin, the hormone that makes breast milk, can stop periods.', 'fact', 'Nature’s pause button.', 'Correct! High prolactin can block ovulation. That’s partly why breastfeeding can delay periods.', 'Some medicines can raise prolactin too.', 'NHS: Prolactinoma', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-08', 'hormones-101', 4, 'Thyroid problems can only make periods lighter, never heavier.', 'myth', 'Two directions.', 'Not true! An underactive thyroid can cause heavy periods, and an overactive one can make them lighter or less frequent.', 'Thyroid checks are a common test for period problems.', 'NHS: Underactive thyroid', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-09', 'hormones-101', 4, 'Cortisol, the stress hormone, can interfere with the brain signals that run your cycle.', 'fact', 'Stress travels.', 'Correct! High stress can disrupt GnRH pulses, delaying ovulation and periods.', 'That’s why a stressful month can mean a late period.', 'Endocrine Society: Stress', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-4-10', 'hormones-101', 4, 'Insulin can push the ovaries to make more androgens.', 'fact', 'Sugar hormone, hair hormone?', 'Correct! High insulin levels can increase androgen production, which is part of how PCOS works.', 'That’s why some PCOS treatments target insulin.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-01', 'hormones-101', 5, 'FSH and LH are made in the ovaries.', 'myth', 'Follow the chain upwards.', 'Not true! FSH and LH are made by the pituitary gland in your brain. They act on the ovaries.', 'Their full names are follicle-stimulating and luteinising hormone.', 'Endocrine Society: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-02', 'hormones-101', 5, 'Some endometriosis medicines switch off the ovaries for a while by acting on GnRH signals.', 'fact', 'Turn the system off.', 'Correct! GnRH-based medicines can calm the HPO axis, lowering oestrogen and easing symptoms.', 'They’re usually used for a limited time.', 'NHS: Endometriosis treatment', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-03', 'hormones-101', 5, 'Inhibin is a hormone that boosts FSH.', 'myth', 'The name is a clue.', 'Not true! Inhibin, made by the ovaries, inhibits FSH, as its name suggests.', 'It helps stop too many follicles growing at once.', 'Endocrine Society: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-04', 'hormones-101', 5, 'SHBG carries sex hormones in the blood, and only the ‘free’ part is active.', 'fact', 'Some hormones are passengers.', 'Correct! Sex hormone-binding globulin holds onto hormones, so only the unbound part can act.', 'Low SHBG means more free testosterone.', 'Cleveland Clinic: SHBG', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-05', 'hormones-101', 5, 'Oestrogen and progesterone are made from protein.', 'myth', 'Steroid hormones.', 'Not true! They’re steroid hormones made from cholesterol.', 'Your body makes most of its own cholesterol.', 'Cleveland Clinic: Steroid hormones', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-06', 'hormones-101', 5, 'Fat tissue can turn androgens into oestrogen using an enzyme called aromatase.', 'fact', 'Fat is active.', 'Correct! This is how most oestrogen is made after menopause.', 'Some breast cancer medicines block aromatase.', 'Cleveland Clinic: Estrogen', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-07', 'hormones-101', 5, 'Melatonin and oestrogen are made by the same gland.', 'myth', 'Two very different places.', 'Not true! Melatonin comes from the pineal gland in the brain, while most oestrogen comes from the ovaries.', 'The pineal gland is about the size of a grain of rice.', 'Cleveland Clinic: Hormones', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-08', 'hormones-101', 5, 'The pituitary makes both prolactin and TSH, the hormone that tells your thyroid to work.', 'fact', 'Master gland, many jobs.', 'Correct! The pituitary controls many glands, including the thyroid and breasts.', 'It also makes growth hormone.', 'NHS: Pituitary gland', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-09', 'hormones-101', 5, 'Kisspeptin is a protein in saliva with nothing to do with hormones.', 'myth', 'Sweet name, big job.', 'Not true! Kisspeptin is made in the brain and helps switch on GnRH, so it’s key to starting puberty.', 'It was named after Hershey’s Kisses, made in the town where it was discovered.', 'Endocrine Society: Puberty', 'approved', 'Spot it content team', true, now()),
  ('hormones-101-5-10', 'hormones-101', 5, 'A ‘normal’ hormone result can depend on which day of the cycle the blood test was taken.', 'fact', 'Timing matters.', 'Correct! Hormones swing so much that doctors often ask for tests on specific cycle days.', 'Progesterone is often checked about a week before a period.', 'NHS: Hormone tests', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-01', 'skin-hormones', 1, 'Spots often pop up in the days before your period.', 'fact', 'Watch your skin across a month.', 'True. Hormone changes before a period can make skin oilier and spots more likely.', 'Some people notice spots in the same place each month.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-02', 'skin-hormones', 1, 'Spots happen because you didn’t wash your face enough.', 'myth', 'What’s happening under the skin?', 'Myth. Acne comes from hormones, oil and blocked pores, not from being dirty.', 'Acne starts when pores get blocked with oil and dead skin cells.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-03', 'skin-hormones', 1, 'Some hormones can make your skin extra oily.', 'fact', 'Even girls make them.', 'True. Hormones called androgens make oil glands bigger and busier, which can lead to spots.', 'Oil glands are busiest on your face, back and chest.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-04', 'skin-hormones', 1, 'Chocolate has been proven to cause spots.', 'myth', 'What does the evidence say?', 'Myth. There’s no strong evidence chocolate causes acne. A balanced diet is good for skin overall.', NULL, 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-05', 'skin-hormones', 1, 'Squeezing a spot helps it heal faster.', 'myth', 'It can push things deeper.', 'Myth. Squeezing can spread bacteria and leave scars. Hands off is best.', 'Picking can leave marks that last much longer than the spot itself.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-06', 'skin-hormones', 1, 'Most teenagers get spots at some point.', 'fact', 'You’re far from alone.', 'True. Acne is super common in the teen years.', 'About 95 out of 100 people aged 11 to 30 get acne at some point.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-07', 'skin-hormones', 1, 'Spots can show up on your back and chest, not just your face.', 'fact', 'Not only the face.', 'True. Anywhere with lots of oil glands can get spots.', 'Breathable clothes when you work out can help with back spots.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-08', 'skin-hormones', 1, 'Hormonal acne stops the moment you turn 20.', 'myth', 'Think about adults too.', 'Myth. It can carry on into adulthood, or even start later in life.', 'Adult acne is more common in women than in men.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-09', 'skin-hormones', 1, 'Hormones like testosterone can make the oil glands in your skin bigger and busier.', 'fact', 'Which hormones rise in puberty for everyone?', 'Yep! Androgens, including testosterone, boost oil production. More oil can mean more blocked pores.', 'Your face has more oil glands than almost anywhere else.', 'American Academy of Dermatology: Acne causes', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-1-10', 'skin-hormones', 1, 'Spots are contagious.', 'myth', 'Can you catch them from a friend?', 'Nope! You can’t catch acne from someone else.', 'Acne is the most common skin condition in teens.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-01', 'skin-hormones', 2, 'For most people, washing your face twice a day is plenty.', 'fact', 'More isn’t always better.', 'True. Washing more often can irritate skin and make spots worse.', 'Lukewarm water is kinder to skin than very hot water.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-02', 'skin-hormones', 2, 'Scrubbing hard gets rid of spots faster.', 'myth', 'Be gentle.', 'Myth. Harsh scrubbing irritates your skin. Gentle cleansing works better.', NULL, 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-03', 'skin-hormones', 2, '‘Non-comedogenic’ on a label is just a fancy word for expensive.', 'myth', 'Comedones are blocked pores.', 'Myth. It means the product is made not to clog pores, which is worth looking for if you get spots.', 'Comedo is the medical name for a blackhead or whitehead.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-04', 'skin-hormones', 2, 'Darker skin doesn’t need sun cream.', 'myth', 'The sun reaches every skin tone.', 'Myth. All skin tones can be damaged by the sun, and sun can make dark marks from spots last longer.', 'Sun cream also helps protect against skin cancer.', 'NHS: Sunscreen and sun safety', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-05', 'skin-hormones', 2, 'Some spot treatments make skin a bit dry or sensitive at first.', 'fact', 'Skin needs time to adjust.', 'True. Mild dryness or redness is common at the start. A pharmacist can tell you how to use them.', NULL, 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-06', 'skin-hormones', 2, 'Toothpaste is a great spot treatment.', 'myth', 'It was made for teeth.', 'Myth. Toothpaste can irritate and dry your skin. Products made for spots are a better bet.', NULL, 'British Association of Dermatologists: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-07', 'skin-hormones', 2, 'Taking your make-up off before bed is good for your skin.', 'fact', 'Pores need a break overnight.', 'True. Make-up left on overnight can clog pores.', 'Washing make-up brushes regularly helps too.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-08', 'skin-hormones', 2, 'A good acne cream clears skin overnight.', 'myth', 'Patience is the secret ingredient.', 'Myth. Most acne treatments take 6 to 8 weeks to show a real difference.', 'Take a photo now so you can see your progress in a couple of months.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-09', 'skin-hormones', 2, 'Benzoyl peroxide, a common spot treatment, can bleach towels and pillowcases.', 'fact', 'Bleach-y name, bleach-y habits?', 'Yep! It can leave pale patches on fabric, so white towels and pillowcases are a smart idea.', 'It also works by killing the bacteria linked to spots.', 'American Academy of Dermatology: Benzoyl peroxide', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-2-10', 'skin-hormones', 2, 'Oily skin doesn’t need moisturiser.', 'myth', 'Is oil the same as water?', 'Nope! Oily skin can still be dry or dehydrated, especially with spot treatments. A light, oil-free moisturiser helps.', 'Look for ‘non-comedogenic’ on the label.', 'American Academy of Dermatology: Oily skin', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-01', 'skin-hormones', 3, 'Deep, painful spots that leave scars are worth seeing a doctor about.', 'fact', 'Some acne needs stronger help.', 'True. Prescription treatments can help prevent scarring.', 'Dermatologists are doctors who specialise in skin.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-02', 'skin-hormones', 3, 'A pharmacist can help with mild spots, no appointment needed.', 'fact', 'You don’t always need a doctor.', 'True. They can recommend creams and gels and tell you when to see a doctor.', 'Benzoyl peroxide is a common pharmacy spot treatment.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-03', 'skin-hormones', 3, 'If acne is getting you down, that alone is a good reason to get help.', 'fact', 'Feelings count too.', 'True. Acne can affect confidence and mood, and you deserve support.', 'Asking for help isn’t vain. Skin health is health.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-04', 'skin-hormones', 3, 'Dark marks left by spots are always there for good.', 'myth', 'Marks and scars are different things.', 'Myth. Dark marks usually fade over months. Sun protection helps them fade faster.', 'These dark marks are more common on darker skin tones.', 'British Association of Dermatologists: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-05', 'skin-hormones', 3, 'Spots plus extra hair on your face or body can be a clue to a hormone condition like PCOS.', 'fact', 'Look at the bigger picture.', 'True. If acne comes with extra hair or irregular periods, a doctor may check for PCOS.', 'PCOS is one of the most common hormone conditions in women.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-06', 'skin-hormones', 3, 'Acne just has to run its course. Nothing really helps.', 'myth', 'Treatment exists.', 'Myth. Acne can be treated, so you don’t have to wait it out.', NULL, 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-07', 'skin-hormones', 3, 'Some stronger acne medicines need regular check-ups.', 'fact', 'Strong medicines need a watchful eye.', 'True. Check-ups make sure the treatment is working safely.', NULL, 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-08', 'skin-hormones', 3, 'Sudden bad acne as an adult is always down to stress.', 'myth', 'There can be other causes.', 'Myth. Stress can play a part, but hormones and medicines can too. A doctor can help work it out.', 'Some medicines can trigger acne as a side effect.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-09', 'skin-hormones', 3, 'Changing your pillowcase often can help if you get spots.', 'fact', 'What does your face rest on every night?', 'Yep! Pillowcases collect oil, sweat and hair products, so a fresh one a couple of times a week can help.', 'Hair products near your hairline can block pores too.', 'American Academy of Dermatology: Acne tips', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-3-10', 'skin-hormones', 3, 'You have to wait until acne is really bad before seeing a GP.', 'myth', 'Is there a minimum level of spots?', 'Nope! If spots bother you or treatments from the pharmacy aren’t working, you can see a GP at any time.', 'Treating acne early can help stop scars.', 'NHS: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-01', 'skin-hormones', 4, 'Acne starts when oil and dead skin cells block hair follicles.', 'fact', 'What clogs a pore?', 'Correct! Sebum and dead skin cells form a plug, and that’s where spots begin.', 'Each pore is actually the opening of a hair follicle.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-02', 'skin-hormones', 4, 'Blackheads are dirt trapped in your pores.', 'myth', 'Why are they dark?', 'Not true! The dark colour comes from oil and skin cells reacting with air, not dirt. Scrubbing won’t fix them.', 'Whiteheads are the same plug with skin over the top.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-03', 'skin-hormones', 4, 'A bacterium called Cutibacterium acnes plays a part in red, inflamed spots.', 'fact', 'A skin resident.', 'Correct! It lives on everyone’s skin, but in blocked pores it can trigger inflammation.', 'It used to be called Propionibacterium acnes.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-04', 'skin-hormones', 4, 'Retinoids work by drying spots out with alcohol.', 'myth', 'Think skin cell turnover.', 'Not true! Retinoids speed up skin cell turnover, which stops pores clogging.', 'Results usually take 8 to 12 weeks.', 'American Academy of Dermatology: Retinoids', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-05', 'skin-hormones', 4, 'Retinoids can make your skin more sensitive to the sun.', 'fact', 'Fresh skin, fragile skin.', 'Correct! Use sun cream daily when using a retinoid.', 'Many people use retinoids at night for this reason.', 'American Academy of Dermatology: Retinoids', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-06', 'skin-hormones', 4, 'Benzoyl peroxide works by switching off your hormones.', 'myth', 'What does it actually target?', 'Not true! It kills acne bacteria and helps unclog pores. It doesn’t touch your hormones.', 'Bacteria don’t become resistant to it, unlike antibiotics.', 'American Academy of Dermatology: Benzoyl peroxide', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-07', 'skin-hormones', 4, 'Salicylic acid helps unclog pores by loosening dead skin cells.', 'fact', 'BHA.', 'Correct! It’s a beta hydroxy acid that can get into oily pores.', 'It comes from the same family as aspirin.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-08', 'skin-hormones', 4, 'Acne scars and dark marks left after spots are the same thing.', 'myth', 'Texture vs colour.', 'Not true! Dark marks are colour changes that usually fade. Scars change the skin’s texture and are more lasting.', 'Sun cream helps dark marks fade faster.', 'American Academy of Dermatology: Acne scars', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-09', 'skin-hormones', 4, 'Darker skin tones are more likely to get dark marks after spots.', 'fact', 'Melanin reacts.', 'Correct! This is called post-inflammatory hyperpigmentation, and it’s common in brown and Black skin.', 'Treating spots early helps prevent marks.', 'American Academy of Dermatology: Dark spots', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-4-10', 'skin-hormones', 4, 'Hormonal acne mostly shows up on the forehead.', 'myth', 'Lower down?', 'Not quite! Hormone-linked acne often shows up on the jawline, chin and lower face.', 'It can flare before a period.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-01', 'skin-hormones', 5, 'Isotretinoin, a strong acne medicine, must never be taken during pregnancy because it can harm a baby.', 'fact', 'Strict rules.', 'Correct! That’s why people taking it follow strict safety rules and have regular check-ups.', 'It’s only prescribed by specialists in the UK.', 'NHS: Isotretinoin', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-02', 'skin-hormones', 5, 'Spironolactone is an antibiotic used for acne.', 'myth', 'Think anti-androgen.', 'Not true! It blocks the effect of androgens on the skin. It’s not an antibiotic.', 'It was first made as a blood pressure medicine.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-03', 'skin-hormones', 5, 'Acne antibiotics are often combined with benzoyl peroxide to help stop bacteria becoming resistant.', 'fact', 'Teamwork.', 'Correct! Using them together lowers the chance of antibiotic resistance.', 'Antibiotics for acne are usually limited to a few months.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-04', 'skin-hormones', 5, 'Azelaic acid can help with both acne and dark marks.', 'fact', 'Two jobs.', 'Correct! It calms spots and can fade post-acne dark marks.', 'It’s often safe to use in pregnancy.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-05', 'skin-hormones', 5, 'Oil production in the skin is controlled mainly by oestrogen.', 'myth', 'Which hormone turns oil up?', 'Not true! Androgens drive oil production. Oestrogen tends to turn it down.', 'That’s why acne often flares when androgen effects are higher.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-06', 'skin-hormones', 5, 'Niacinamide, a form of vitamin B3, can help calm redness and oily skin.', 'fact', 'A vitamin in your skincare.', 'Correct! Niacinamide can help reduce redness and oil, and most skin types handle it well.', 'It’s found in many moisturisers and serums.', 'Cleveland Clinic: Niacinamide', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-07', 'skin-hormones', 5, 'Acne in women over 25 is rare.', 'myth', 'Is acne just for teens?', 'Not true! Adult acne is common in women, often around the jaw and chin.', 'Many women first get acne as adults.', 'American Academy of Dermatology: Acne', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-08', 'skin-hormones', 5, 'Hidradenitis suppurativa causes painful lumps in places like the armpits and groin, and it’s not caused by poor hygiene.', 'fact', 'Not about washing.', 'Correct! It’s a long-term inflammatory skin condition, and good treatments exist.', 'It often starts after puberty.', 'NHS: Hidradenitis suppurativa', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-09', 'skin-hormones', 5, 'Rosacea and acne are the same condition.', 'myth', 'Similar look, different cause.', 'Not true! Rosacea causes flushing, redness and sometimes bumps, usually in adults. It needs different treatment.', 'Rosacea usually has no blackheads.', 'NHS: Rosacea', 'approved', 'Spot it content team', true, now()),
  ('skin-hormones-5-10', 'skin-hormones', 5, 'SPF 50 lets you stay in the sun twice as long as SPF 25 without reapplying.', 'myth', 'How long does sun cream last?', 'Not true! Whatever the SPF, reapply at least every 2 hours and after swimming or sweating.', 'Most people put on less than half the amount needed.', 'NHS: Sunscreen and sun safety', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-01', 'mood-hormones', 1, 'It’s normal for your mood to go up and down.', 'fact', 'Are you meant to feel the same every day?', 'Yep! Everyone has ups and downs. Moods shift with sleep, stress, hormones and what’s going on in your life.', 'Noticing your moods is the first step to looking after them.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-02', 'mood-hormones', 1, 'Feeling grumpy before your period means you’re just a moody person.', 'myth', 'Is it you or your cycle?', 'Nope! Irritability before a period is a really common PMS symptom. It says nothing about who you are.', 'Logging moods in Spot it can show if they follow your cycle.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-03', 'mood-hormones', 1, 'Oestrogen can affect serotonin, a brain chemical linked to mood.', 'fact', 'Hormones talk to your brain too.', 'Yep! When oestrogen rises and falls, it can nudge serotonin, which may be one reason moods change across the cycle.', 'Serotonin also helps with sleep and appetite.', 'Cleveland Clinic: Serotonin', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-04', 'mood-hormones', 1, 'Only adults get PMS.', 'myth', 'When do periods start?', 'Nope! Girls can get PMS from their teens onwards.', 'PMS symptoms can change as you get older.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-05', 'mood-hormones', 1, 'Crying more easily before your period is a common PMS symptom.', 'fact', 'Is it common or rare?', 'Yep! Feeling teary, sensitive or low before a period is really common, and it usually eases once your period starts.', 'Be extra kind to yourself on those days.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-06', 'mood-hormones', 1, 'If you feel anxious, it’s always because of your period.', 'myth', 'Is there only one cause of worry?', 'Nope! Hormones can play a part, but worry has lots of causes, like school, friends and big changes.', 'Tracking can help you see what’s hormones and what’s life.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-07', 'mood-hormones', 1, 'Talking to someone you trust can make tough feelings easier to handle.', 'fact', 'A problem shared...', 'Yep! Saying how you feel out loud often makes it feel smaller and more manageable.', 'It can be a friend, family member, teacher or school nurse.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-08', 'mood-hormones', 1, 'Getting outside in daylight can give your mood a lift.', 'fact', 'Think sunshine.', 'Yep! Daylight and fresh air are simple mood boosters, even on a cloudy day.', 'Morning light helps your sleep too.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-09', 'mood-hormones', 1, 'Ignoring big feelings makes them go away faster.', 'myth', 'Do pushed-down feelings vanish?', 'Nope! Bottling feelings up can make them build. Naming them and talking about them helps them pass.', 'Even writing one sentence about how you feel can help.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-1-10', 'mood-hormones', 1, 'PMS mood changes usually ease once your period starts.', 'fact', 'Think about timing.', 'Yep! For most people, PMS symptoms fade within a few days of the period starting.', 'That timing is a big clue doctors use.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-01', 'mood-hormones', 2, 'Some people notice more energy and confidence in the days before ovulation.', 'fact', 'Oestrogen is climbing.', 'Yep! Rising oestrogen in the first half of the cycle can come with a lift in energy for some people.', 'Not everyone notices it, and that’s fine too.', 'Cleveland Clinic: Menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-02', 'mood-hormones', 2, 'The week before a period feels the same for everyone.', 'myth', 'Are any two cycles the same?', 'Nope! Some people barely notice it, while others feel big changes. Both are normal.', 'Your pattern is personal to you.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-03', 'mood-hormones', 2, 'Tracking your mood for a few months can show whether it follows your cycle.', 'fact', 'What do doctors ask for?', 'Yep! A symptom diary over two or three cycles is one of the best ways to spot PMS.', 'Spot it’s mood log is made for this.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-04', 'mood-hormones', 2, 'PMS symptoms start on the first day of your period.', 'myth', 'P-M-S. What does the P-M stand for?', 'Nope! The ‘pre’ in premenstrual means before. Symptoms show up in the days or weeks before your period.', 'They usually ease once bleeding starts.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-05', 'mood-hormones', 2, 'Irritability is one of the most common PMS symptoms.', 'fact', 'Snappy?', 'Yep! Feeling irritable or short-tempered is one of the most reported PMS symptoms.', 'A quick walk or a few slow breaths can take the edge off.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-06', 'mood-hormones', 2, 'Hormones only affect your body, not your thoughts or feelings.', 'myth', 'Where do hormones travel?', 'Nope! Hormones reach your brain too, so they can affect mood, focus and sleep.', 'Your brain has receptors for oestrogen and progesterone.', 'Cleveland Clinic: Hormones', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-07', 'mood-hormones', 2, 'Feeling bloated or tired can make your mood dip too.', 'fact', 'Body and mind are connected.', 'Yep! Physical PMS symptoms like bloating and tiredness can drag your mood down with them.', 'Looking after your body helps your mood too.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-08', 'mood-hormones', 2, 'A bad mood before your period is just an excuse.', 'myth', 'Is PMS real?', 'Nope! PMS is a real, recognised condition. Your feelings are valid.', 'Doctors take PMS seriously and can help if it’s tough.', 'NHS: PMS', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-09', 'mood-hormones', 2, 'Progesterone, which rises after ovulation, can make some people feel sleepier.', 'fact', 'Think of a cosy hormone.', 'Yep! Progesterone has a slightly calming effect, so some people feel more tired in the second half of their cycle.', 'Your body temperature rises a little at the same time.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-2-10', 'mood-hormones', 2, 'Low mood that lasts most of the month, not just before your period, is worth talking to a doctor about.', 'fact', 'Is it timed with your cycle?', 'Yep! If low mood sticks around all month, it might not be PMS, and a doctor can help work out what’s going on.', 'You don’t need to wait until things feel really bad.', 'NHS: Depression in young people', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-01', 'mood-hormones', 3, 'Even a 10-minute walk can boost your mood.', 'fact', 'Small moves count.', 'Yep! Short bursts of movement can lift your mood and ease stress.', 'Walking with a friend is a double win.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-02', 'mood-hormones', 3, 'Scrolling on your phone late at night helps you unwind.', 'myth', 'What does a bright screen tell your brain?', 'Nope! Late scrolling can keep your brain buzzing and push back sleep, which can make moods worse the next day.', 'Try putting the phone down an hour before bed.', 'NHS: Sleep tips for teens', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-03', 'mood-hormones', 3, 'Writing your feelings down can help you make sense of them.', 'fact', 'Pen and paper power.', 'Yep! Journalling can help you notice patterns and feel calmer.', 'Spot it’s notes are a good place to start.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-04', 'mood-hormones', 3, 'Asking for help with your feelings means you’re weak.', 'myth', 'Do strong people ask for help?', 'Nope! Asking for help takes courage, and it’s one of the best things you can do for yourself.', 'Lots of people feel better once they’ve talked to someone.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-05', 'mood-hormones', 3, 'Breathing out for longer than you breathe in can help calm your body down.', 'fact', 'Slow it down.', 'Yep! Long, slow out-breaths tell your nervous system it’s OK to relax.', 'Try breathing in for 4 and out for 6.', 'NHS: Breathing exercises for stress', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-06', 'mood-hormones', 3, 'If feelings ever get too much, or you think about hurting yourself, you should reach out for help straight away.', 'fact', 'You deserve support.', 'Yes. Talk to a trusted adult or a doctor, or call a helpline. In an emergency, call your local emergency number.', 'You are never a burden for asking for help.', 'NHS: Get help for suicidal thoughts', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-07', 'mood-hormones', 3, 'Sugary snacks are the best fix for a low mood.', 'myth', 'Quick lift, then...?', 'Nope! Sugar can give a quick lift, then a slump. Regular meals, sleep and movement are better for steady moods.', 'A treat is fine, it just isn’t a mood fix.', 'NHS: Eat well', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-08', 'mood-hormones', 3, 'Getting enough sleep makes stress easier to handle.', 'fact', 'Ever felt everything is worse when you’re tired?', 'Yep! Sleep helps your brain manage emotions, so good sleep makes tough days easier.', 'Teens need about 8 to 10 hours a night.', 'NHS: Sleep tips for teens', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-09', 'mood-hormones', 3, 'You have to wait until things are really bad before talking to a school nurse or doctor.', 'myth', 'Is there a minimum?', 'Nope! You can ask for help with your feelings at any time. Early support often helps most.', 'School nurses hear about feelings all the time.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-3-10', 'mood-hormones', 3, 'Doing something you enjoy, like music or drawing, counts as looking after your mental health.', 'fact', 'Fun counts.', 'Yep! Hobbies give your mind a break and can really lift your mood.', 'Even 15 minutes a day of something you love helps.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-01', 'mood-hormones', 4, 'Allopregnanolone, made from progesterone, acts on the same brain receptors as some calming medicines.', 'fact', 'GABA.', 'Correct! It acts on GABA receptors, which helps explain mood changes for some people.', 'These receptors are the brain’s calm-down system.', 'NIH: PMDD sensitivity study (2017)', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-02', 'mood-hormones', 4, 'PMDD is caused by having abnormal hormone levels.', 'myth', 'Levels or sensitivity?', 'Not true! People with PMDD usually have normal hormone levels. Their brains react more strongly to normal changes.', 'This was shown in research at the NIH.', 'NIH: PMDD sensitivity study (2017)', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-03', 'mood-hormones', 4, 'To diagnose PMDD, doctors usually ask for daily symptom tracking over at least two cycles.', 'fact', 'Data over time.', 'Correct! Tracking shows if symptoms follow the cycle.', 'Spot it logs can help.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-04', 'mood-hormones', 4, 'Antidepressants for PMDD only work after months of use.', 'myth', 'Speed?', 'Not true! For PMDD, SSRIs often work within days, so some people take them only before their period.', 'This is different from depression.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-05', 'mood-hormones', 4, 'Some people take SSRIs only in the second half of their cycle to treat PMDD.', 'fact', 'Timed treatment.', 'Correct! This is called luteal-phase dosing.', 'A doctor can help decide what’s best.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-06', 'mood-hormones', 4, 'PMS and PMDD symptoms last all month long.', 'myth', 'Timing is the clue.', 'Not true! They happen in the luteal phase and ease within a few days of the period starting.', 'Symptoms all month point to something else.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-07', 'mood-hormones', 4, 'Oestrogen can boost serotonin activity in the brain.', 'fact', 'Feel-good link.', 'Correct! This is one reason falling oestrogen can affect mood.', 'Serotonin also affects sleep and appetite.', 'Cleveland Clinic: Estrogen', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-08', 'mood-hormones', 4, 'Only a tiny number of people get mood changes before a period.', 'myth', 'How many?', 'Not true! As many as 3 in 4 women notice some PMS symptoms.', 'Most cases are mild.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-09', 'mood-hormones', 4, 'Premenstrual exacerbation is when an existing condition, like depression, gets worse before a period.', 'fact', 'PME.', 'Correct! It’s different from PMDD, and tracking helps tell them apart.', 'Asthma and migraines can also worsen.', 'IAPMD: PME', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-4-10', 'mood-hormones', 4, 'Cortisol only rises when something bad happens.', 'myth', 'Morning hormone.', 'Not true! Cortisol follows a daily rhythm and peaks in the morning to help you wake up.', 'It’s called the cortisol awakening response.', 'Cleveland Clinic: Cortisol', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-01', 'mood-hormones', 5, 'Around 3 to 8% of women are thought to have PMDD.', 'fact', 'Rarer than PMS.', 'Correct! PMDD is much less common than PMS, but it can be severe.', 'It’s often missed.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-02', 'mood-hormones', 5, 'PMDD is not recognised as its own diagnosis.', 'myth', 'Check the manuals.', 'Not true! PMDD is listed as a depressive disorder in the DSM-5 and in the WHO’s ICD-11.', 'It was added to DSM-5 in 2013.', 'American Psychiatric Association: DSM-5', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-03', 'mood-hormones', 5, 'PMDD symptoms usually ease within a few days after a period starts.', 'fact', 'Relief arrives.', 'Correct! The timing is a key feature.', 'This pattern repeats each cycle.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-04', 'mood-hormones', 5, 'Dopamine is the brain’s sleep hormone.', 'myth', 'Wrong chemical.', 'Not true! Melatonin is the sleep hormone. Dopamine is linked to reward and motivation.', 'Dopamine is a neurotransmitter.', 'Cleveland Clinic: Dopamine', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-05', 'mood-hormones', 5, 'Most of the body’s serotonin is made in the gut.', 'fact', 'Gut feelings.', 'Correct! About 90% is made in the gut, though brain serotonin is made separately.', 'The gut has its own nervous system.', 'Cleveland Clinic: Serotonin', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-06', 'mood-hormones', 5, 'Seasonal low mood (SAD) has nothing to do with daylight.', 'myth', 'Winter blues.', 'Not true! SAD is linked to less daylight in autumn and winter.', 'Light therapy can help some people.', 'NHS: Seasonal affective disorder', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-07', 'mood-hormones', 5, 'CBT, a talking therapy, can help some people with PMDD.', 'fact', 'Tools for the mind.', 'Correct! CBT can help people manage symptoms.', 'It’s often combined with other treatments.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-08', 'mood-hormones', 5, 'Endorphins are hormones that make you feel more pain.', 'myth', 'Natural painkillers.', 'Not true! Endorphins are the body’s own painkillers and mood lifters.', 'Laughing with friends can release endorphins too.', 'Cleveland Clinic: Endorphins', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-09', 'mood-hormones', 5, 'Oxytocin, sometimes called the ‘cuddle hormone’, is released during hugs and close contact.', 'fact', 'Warm and fuzzy.', 'Correct! Oxytocin helps with bonding and can lower stress.', 'A long hug from a friend or family member can give you a boost.', 'Cleveland Clinic: Oxytocin', 'approved', 'Spot it content team', true, now()),
  ('mood-hormones-5-10', 'mood-hormones', 5, 'Feeling better after exercise is all in your head, with no real change in the body.', 'myth', 'Endorphins.', 'Not true! Exercise releases endorphins and other brain chemicals that lift mood.', 'Even short sessions help.', 'NHS Every Mind Matters', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-01', 'sleep-cycle', 1, 'Teenagers need about 8 to 10 hours of sleep a night.', 'fact', 'More than adults.', 'Yep! Teens need more sleep than adults because their bodies and brains are still growing.', 'Most teens get less than this on school nights.', 'American Academy of Sleep Medicine: Sleep needs', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-02', 'sleep-cycle', 1, 'You can fully catch up on a week of lost sleep with one big lie-in.', 'myth', 'Can you pay it all back in one go?', 'Nope! A lie-in helps a bit, but it can’t fully undo a week of short nights, and it can mess with your body clock.', 'Regular sleep beats catch-up sleep.', 'Sleep Foundation: Sleep debt', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-03', 'sleep-cycle', 1, 'Your body has a built-in 24-hour clock called your circadian rhythm.', 'fact', 'Tick tock.', 'Yep! It controls when you feel sleepy and alert, and it’s set mainly by light.', '‘Circadian’ comes from Latin for ‘about a day’.', 'Sleep Foundation: Circadian rhythm', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-04', 'sleep-cycle', 1, 'Teen body clocks naturally shift later, so feeling sleepy later at night is normal.', 'fact', 'Night owl phase?', 'Yep! In the teen years, your body releases its sleep hormone later, so you feel sleepy later.', 'This shift usually eases in your twenties.', 'Sleep Foundation: Teens and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-05', 'sleep-cycle', 1, 'Light from screens has no effect on sleep.', 'myth', 'What does light tell your brain?', 'Nope! Bright screen light at night can tell your brain it’s still daytime and make it harder to fall asleep.', 'Night mode helps a little, but putting the phone away helps more.', 'Sleep Foundation: Screens and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-06', 'sleep-cycle', 1, 'Melatonin is the hormone that tells your body it’s time to sleep.', 'fact', 'It comes out in the dark.', 'Yep! Your brain releases melatonin as it gets dark, helping you feel sleepy.', 'Light, especially bright light, slows melatonin down.', 'Sleep Foundation: Melatonin', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-07', 'sleep-cycle', 1, 'Everyone needs exactly 8 hours of sleep, no more, no less.', 'myth', 'Is there a magic number?', 'Nope! Sleep needs vary with age and from person to person. Teens usually need 8 to 10.', 'Waking up refreshed is a good sign you’re getting enough.', 'American Academy of Sleep Medicine: Sleep needs', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-08', 'sleep-cycle', 1, 'Most vivid dreams happen during REM sleep.', 'fact', 'R-E-M stands for rapid eye...', 'Yep! REM stands for rapid eye movement, and it’s when the most vivid dreams usually happen.', 'Your eyes really do dart around under your eyelids.', 'Sleep Foundation: Stages of sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-09', 'sleep-cycle', 1, 'A can of cola in the evening won’t affect your sleep.', 'myth', 'What’s in cola?', 'Nope! Cola contains caffeine, which can keep you awake for hours.', 'Some iced teas and chocolate contain caffeine too.', 'NHS: Sleep tips for teens', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-1-10', 'sleep-cycle', 1, 'Not getting enough sleep can make it harder to concentrate at school.', 'fact', 'Ever had a foggy morning?', 'Yep! Sleep helps your brain store what you learned and stay focused.', 'Sleep is when your brain files away the day’s memories.', 'NHS: Sleep tips for teens', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-01', 'sleep-cycle', 2, 'Some people sleep worse in the few days before their period.', 'fact', 'Hormones are on the move.', 'Yep! Falling hormone levels before a period can make sleep lighter or more broken for some people.', 'Logging sleep and your cycle together can show if this is you.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-02', 'sleep-cycle', 2, 'Your body temperature is a little higher after ovulation, which can make sleep feel lighter.', 'fact', 'Progesterone warms you up.', 'Yep! After ovulation, progesterone nudges your temperature up a bit, and a warmer body can sleep less deeply.', 'A cooler bedroom can help.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-03', 'sleep-cycle', 2, 'Period cramps can’t wake you up.', 'myth', 'Can pain interrupt sleep?', 'Nope! Cramps can wake people up or make it hard to drift off. A hot water bottle or a painkiller before bed can help.', 'Lying curled on your side eases cramps for some.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-04', 'sleep-cycle', 2, 'Sleeping on your side with your knees tucked up can ease cramps for some people.', 'fact', 'Curl up.', 'Yep! This position takes pressure off your tummy muscles, which some people find comfier during cramps.', 'Some people call it the foetal position.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-05', 'sleep-cycle', 2, 'Feeling extra tired on your period is always a sign of something serious.', 'myth', 'Is it common?', 'Nope! Feeling more tired on your period is common. But if you’re wiped out all the time, check your iron with a doctor.', 'Heavy periods are a common reason for low iron.', 'NHS: Iron deficiency anaemia', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-06', 'sleep-cycle', 2, 'Low iron from heavy periods can leave you tired even after a full night’s sleep.', 'fact', 'Iron carries oxygen.', 'Yep! Without enough iron, your blood carries less oxygen, so you can feel tired no matter how much you sleep.', 'A simple blood test can check your iron.', 'NHS: Iron deficiency anaemia', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-07', 'sleep-cycle', 2, 'Night sweats only happen to older women.', 'myth', 'Can hormones change at any age?', 'Nope! Some people get night sweats around their period because of hormone changes. They’re also linked to menopause, illness and some medicines.', 'Breathable bedding can help.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-08', 'sleep-cycle', 2, 'A cool bedroom can help you sleep, especially in the second half of your cycle.', 'fact', 'Remember the temperature rise?', 'Yep! Your body needs to cool down to fall asleep, and that can be harder when progesterone is high.', 'Around 16 to 18°C suits most people.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-09', 'sleep-cycle', 2, 'Napping for hours in the afternoon helps you sleep better at night.', 'myth', 'What happens to your sleepiness?', 'Nope! Long naps late in the day can make it harder to fall asleep at night. Keep naps short and early.', 'Around 20 minutes is a good power nap.', 'Sleep Foundation: Napping', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-2-10', 'sleep-cycle', 2, 'Tracking your sleep alongside your cycle can help you spot patterns.', 'fact', 'Data is your friend.', 'Yep! You might notice certain days in your cycle when sleep is harder, so you can plan for them.', 'Spot it can show your logs on the calendar.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-01', 'sleep-cycle', 3, 'Going to bed and waking up at the same times, even at weekends, helps your body clock.', 'fact', 'Body clocks love routine.', 'Yep! A steady routine trains your body clock, so falling asleep and waking up get easier.', 'Even keeping weekends within an hour or so helps.', 'NHS: Sleep tips for teens', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-02', 'sleep-cycle', 3, 'Exercising during the day makes it harder to sleep.', 'myth', 'Tired muscles?', 'Nope! Regular exercise usually helps you sleep better. Just avoid hard workouts right before bed.', 'Morning or afternoon movement is ideal.', 'Sleep Foundation: Exercise and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-03', 'sleep-cycle', 3, 'Putting screens away about an hour before bed can help you fall asleep.', 'fact', 'Wind-down time.', 'Yep! Less light and less scrolling give your brain time to switch off.', 'Try a book, music or a podcast instead.', 'NHS: Sleep tips for teens', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-04', 'sleep-cycle', 3, 'If you can’t sleep, staying in bed and trying harder is the best thing to do.', 'myth', 'Does trying harder to sleep work?', 'Nope! If you can’t sleep after about 20 minutes, get up and do something calm in dim light, then go back when you feel sleepy.', 'This stops your brain linking bed with lying awake.', 'NHS: Insomnia', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-05', 'sleep-cycle', 3, 'Morning daylight helps reset your body clock.', 'fact', 'Sunlight sets the clock.', 'Yep! Bright light in the morning tells your body clock it’s daytime, helping you feel sleepy at the right time later.', 'Even 10 to 15 minutes outside helps.', 'Sleep Foundation: Light and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-06', 'sleep-cycle', 3, 'Energy drinks are a safe fix for feeling tired.', 'myth', 'What’s in them?', 'Nope! Energy drinks are packed with caffeine and sugar and aren’t recommended for children and teens.', 'In the UK, many shops don’t sell them to under-16s.', 'NHS: Energy drinks', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-07', 'sleep-cycle', 3, 'A warm, not hot, bath an hour or two before bed can help you feel sleepy.', 'fact', 'Warm up to cool down.', 'Yep! Your body cools down after a warm bath, and that cooling helps trigger sleep.', 'Too hot or too close to bedtime can have the opposite effect.', 'Sleep Foundation: Bathing and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-08', 'sleep-cycle', 3, 'Snoring is always harmless.', 'myth', 'Is it ‘always’?', 'Nope! Snoring is often harmless, but loud snoring with gasping or pauses in breathing should be checked by a doctor.', 'This can be a sign of sleep apnoea.', 'NHS: Snoring', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-09', 'sleep-cycle', 3, 'Struggling to sleep for weeks is worth talking to a doctor about.', 'fact', 'When does it become a problem?', 'Yep! If poor sleep goes on for weeks and affects your day, a doctor can help work out why.', 'There are good treatments that don’t involve sleeping pills.', 'NHS: Insomnia', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-3-10', 'sleep-cycle', 3, 'Writing a quick to-do list before bed can help quiet a busy mind.', 'fact', 'Brain dump.', 'Yep! Getting tomorrow’s jobs onto paper can stop them going round your head at bedtime.', 'A study found people who wrote to-do lists fell asleep faster.', 'Sleep Foundation: Bedtime routine', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-01', 'sleep-cycle', 4, 'Your core body temperature drops in the evening to help you fall asleep.', 'fact', 'Cool down.', 'Correct! A drop in core temperature is part of your body’s sleep signal.', 'That’s why a cool room helps.', 'Sleep Foundation: Body temperature', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-02', 'sleep-cycle', 4, 'Melatonin is made mainly in the stomach.', 'myth', 'Deep in the brain.', 'Not true! The melatonin that controls sleep is made by the pineal gland in the brain.', 'The pineal gland is about the size of a grain of rice.', 'Sleep Foundation: Melatonin', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-03', 'sleep-cycle', 4, 'Teens release melatonin later at night than adults and young children do.', 'fact', 'Night owl phase.', 'Correct! This is why teens often feel more awake late at night.', 'It’s biology, not laziness.', 'Sleep Foundation: Teens and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-04', 'sleep-cycle', 4, 'Deep sleep mostly happens in the last few hours before you wake.', 'myth', 'First half or second half?', 'Not true! Most deep sleep happens in the first half of the night. REM sleep is more common later.', 'That’s why the start of the night matters.', 'Sleep Foundation: Stages of sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-05', 'sleep-cycle', 4, 'Your body releases most of its growth hormone during deep sleep.', 'fact', 'Growing in your sleep.', 'Correct! Deep sleep is when much of the body’s repair and growth happens.', 'Teens need this sleep to grow.', 'Sleep Foundation: Stages of sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-06', 'sleep-cycle', 4, 'During REM sleep, your muscles are at their most active.', 'myth', 'Paralysed?', 'Not true! Most muscles are temporarily switched off during REM so you don’t act out your dreams.', 'Your eye muscles and breathing keep working.', 'Sleep Foundation: Stages of sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-07', 'sleep-cycle', 4, 'A full sleep cycle lasts roughly 90 minutes.', 'fact', 'Cycles within the night.', 'Correct! You go through several of these cycles each night.', 'Waking at the end of a cycle can feel easier.', 'Sleep Foundation: Stages of sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-08', 'sleep-cycle', 4, 'Adenosine is a brain chemical that wakes you up.', 'myth', 'Builds up through the day.', 'Not true! Adenosine builds up during the day and makes you sleepy. Caffeine blocks it.', 'Sleep clears adenosine away.', 'Sleep Foundation: Caffeine and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-09', 'sleep-cycle', 4, 'Caffeine can stay in your body for 5 hours or more, so an afternoon drink can still affect sleep.', 'fact', 'Half-life.', 'Correct! Half the caffeine can still be around 5 hours later.', 'Some people are more sensitive than others.', 'Sleep Foundation: Caffeine and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-4-10', 'sleep-cycle', 4, 'Sleep problems before a period have nothing to do with hormones.', 'myth', 'What changes before a period?', 'Not true! Falling oestrogen and progesterone before a period are linked to poorer sleep for some people.', 'Tracking can help you spot this.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-01', 'sleep-cycle', 5, 'A part of the brain called the suprachiasmatic nucleus (SCN) is your body’s master clock.', 'fact', 'Above the optic nerves.', 'Correct! The SCN sits in the hypothalamus and uses light signals from your eyes.', 'It has only about 20,000 nerve cells.', 'Sleep Foundation: Circadian rhythm', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-02', 'sleep-cycle', 5, 'Red light at night has the strongest effect on your body clock.', 'myth', 'Which colour?', 'Not true! Blue light has the strongest effect. Dim, warm light is gentler.', 'Your eyes have special cells sensitive to blue light.', 'Sleep Foundation: Light and sleep', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-03', 'sleep-cycle', 5, 'Restless legs syndrome is more common in people with low iron.', 'fact', 'Iron and nerves.', 'Correct! Low iron is linked to restless legs, so doctors often check ferritin.', 'It can get worse in pregnancy.', 'NHS: Restless legs syndrome', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-04', 'sleep-cycle', 5, 'Sleep apnoea only happens in older men.', 'myth', 'Who else?', 'Not true! It can affect anyone, including women and people with PCOS.', 'Loud snoring and daytime sleepiness are clues.', 'NHS: Sleep apnoea', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-05', 'sleep-cycle', 5, 'In the second half of the cycle, people tend to get a little less REM sleep.', 'fact', 'Luteal changes.', 'Correct! Studies show REM sleep often dips in the luteal phase.', 'Light sleep may increase too.', 'Sleep Foundation: Sleep and the menstrual cycle', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-06', 'sleep-cycle', 5, 'Melatonin supplements are recommended for most teens who can’t sleep.', 'myth', 'Advice?', 'Not true! In the UK, melatonin is prescription-only and usually used for specific cases. Sleep habits come first.', 'Talk to a doctor before trying any sleep aid.', 'NHS: Melatonin', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-07', 'sleep-cycle', 5, 'Social jet lag is the gap between your sleep times on school days and free days.', 'fact', 'Weekend lie-ins.', 'Correct! A big gap can leave you feeling jet-lagged every Monday.', 'Keeping weekend sleep within an hour helps.', 'Sleep Foundation: Social jet lag', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-08', 'sleep-cycle', 5, 'Your body clock runs on exactly 24 hours without any help from daylight.', 'myth', 'Slightly off.', 'Not true! Most body clocks run a bit longer than 24 hours, and daylight resets them each day.', 'That’s why morning light matters.', 'Sleep Foundation: Circadian rhythm', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-09', 'sleep-cycle', 5, 'Around menopause, drops in oestrogen can cause hot flushes that wake people at night.', 'fact', 'Night sweats.', 'Correct! Hot flushes at night are a common reason for broken sleep around menopause.', 'Treatments can help.', 'NHS: Menopause', 'approved', 'Spot it content team', true, now()),
  ('sleep-cycle-5-10', 'sleep-cycle', 5, 'Sleeping with the TV on helps you get deeper sleep.', 'myth', 'Light and noise.', 'Not true! Light and noise can disturb sleep even if you don’t fully wake. A dark, quiet room is best.', 'Even small lights in the bedroom can affect melatonin.', 'Sleep Foundation: Bedroom environment', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-01', 'pcos', 1, 'PCOS stands for polycystic ovary syndrome.', 'fact', 'Poly means many.', 'True. It’s a common condition that affects how the ovaries work.', 'PCOS was first described by doctors in the 1930s.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-02', 'pcos', 1, 'PCOS is super rare.', 'myth', 'How common do you think it is?', 'Myth. It’s thought to affect about 1 in 10 women. That could be a few people in your class.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-03', 'pcos', 1, 'PCOS means you have dangerous cysts on your ovaries.', 'myth', 'What are those ‘cysts’ really?', 'Myth. They’re small follicles that hold eggs. They aren’t harmful, and not everyone with PCOS has them.', 'Those follicles are eggs that didn’t fully develop.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-04', 'pcos', 1, 'With PCOS, your ovaries might skip releasing an egg some months.', 'fact', 'Think irregular cycles.', 'True. Skipped ovulation is why periods can be irregular with PCOS.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-05', 'pcos', 1, 'PCOS is caused by something you did.', 'myth', 'What does the research say?', 'Myth. The exact cause isn’t known, but it’s linked to hormones and genes, not anything you did.', 'Scientists are still researching exactly what causes PCOS.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-06', 'pcos', 1, 'PCOS can run in families.', 'fact', 'Genes play a part.', 'True. You’re more likely to have it if a close relative does.', 'If your mum or sister has PCOS, it’s worth knowing the signs.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-07', 'pcos', 1, 'PCOS only affects your ovaries.', 'myth', 'Think insulin, skin and mood.', 'Myth. It can also affect insulin, skin, hair and mood.', 'Many people with PCOS have insulin resistance.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-08', 'pcos', 1, 'There’s no cure for PCOS, but you can manage it really well.', 'fact', 'Managing is the goal.', 'True. Lifestyle changes and medicines can help with most symptoms.', 'Lots of people with PCOS live full, healthy lives.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-09', 'pcos', 1, 'In PCOS, the ‘cysts’ are actually small follicles that haven’t released an egg.', 'fact', 'Are they the scary kind?', 'Yep! They’re tiny fluid-filled sacs that each hold an egg that wasn’t released. They aren’t harmful.', 'The name PCOS is a bit misleading, and experts have talked about changing it.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-1-10', 'pcos', 1, 'You can only get PCOS after you’ve had children.', 'myth', 'When do the signs often show up?', 'Nope! Signs of PCOS often show up in the late teens or early twenties.', 'Many people find out when they try to work out why their periods are irregular.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-01', 'pcos', 2, 'Irregular or missing periods can be a sign of PCOS.', 'fact', 'Look at your cycle pattern.', 'True. It’s one of the most common signs.', 'Having very few periods a year is a sign worth mentioning to a doctor.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-02', 'pcos', 2, 'Extra hair on the face, chest or back can be linked to PCOS.', 'fact', 'Higher androgens are a clue.', 'True. Higher levels of androgens can cause extra hair growth.', 'Extra hair growth has a medical name: hirsutism.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-03', 'pcos', 2, 'Everyone with PCOS has exactly the same symptoms.', 'myth', 'PCOS looks different on everyone.', 'Myth. Some people have lots of symptoms, others only one or two.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-04', 'pcos', 2, 'Thinning hair on your head can be linked to PCOS.', 'fact', 'Androgens affect scalp hair too.', 'True. Some people with PCOS notice thinning or hair loss.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-05', 'pcos', 2, 'One blood test is all it takes to know if you have PCOS.', 'myth', 'Doctors look at several things.', 'Myth. Doctors look at symptoms, blood tests and sometimes an ultrasound scan.', 'An ultrasound scan uses sound waves and doesn’t hurt.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-06', 'pcos', 2, 'Oily skin and stubborn spots can be linked to PCOS.', 'fact', 'Hormones affect skin.', 'True. Higher androgens can make skin oilier and spots more likely.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-07', 'pcos', 2, 'Only people who are overweight get PCOS.', 'myth', 'PCOS shows up in every body type.', 'Myth. People of any weight can have PCOS, though it can make weight gain more likely.', 'PCOS in slimmer people is sometimes called ‘lean PCOS’.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-08', 'pcos', 2, 'Dark, velvety skin patches, often on the neck, can be linked to PCOS.', 'fact', 'Look at the neck or armpits.', 'True. They can be a sign the body isn’t using insulin well, which is common in PCOS.', 'This skin change has a medical name: acanthosis nigricans.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-09', 'pcos', 2, 'PCOS can make it harder for your body to use insulin properly.', 'fact', 'Insulin is the hormone that handles sugar.', 'Yep! This is called insulin resistance, and it’s common in PCOS.', 'Insulin resistance can make the ovaries make more testosterone.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-2-10', 'pcos', 2, 'PCOS always causes weight gain.', 'myth', 'Is there an ‘always’ in PCOS?', 'Nope! Some people with PCOS gain weight more easily, but many don’t. PCOS looks different for everyone.', 'People of any size can have PCOS.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-01', 'pcos', 3, 'Moving your body regularly can help manage PCOS.', 'fact', 'Movement helps insulin work.', 'True. Exercise helps your body use insulin better, which can ease symptoms.', 'Mixing cardio with strength exercise can be helpful.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-02', 'pcos', 3, 'There’s one magic diet that cures PCOS.', 'myth', 'Is there a magic menu?', 'Myth. No diet cures PCOS, but balanced eating can help manage it.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-03', 'pcos', 3, 'For people who are overweight, losing even a little weight can ease PCOS.', 'fact', 'Small changes count.', 'True. Losing around 5 percent of body weight can help with periods and other symptoms.', 'For someone weighing 80 kg, 5 percent is just 4 kg.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-04', 'pcos', 3, 'Medicines can help make periods more regular with PCOS.', 'fact', 'Doctors have options.', 'True. A doctor can suggest treatments for periods and other symptoms.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-05', 'pcos', 3, 'Having PCOS means you can never have children.', 'myth', 'What does the evidence say?', 'Myth. Many people with PCOS have children, some with a little help from treatment.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-06', 'pcos', 3, 'PCOS can affect your mood, and support is out there.', 'fact', 'Feelings matter too.', 'True. People with PCOS are more likely to feel anxious or low. Talking to a doctor can help.', 'You’re not alone: PCOS support groups exist online and in many countries.', 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-07', 'pcos', 3, 'Once you’re diagnosed with PCOS, you never need another check-up.', 'myth', 'Long-term health matters.', 'Myth. Regular check-ups help keep an eye on things like blood sugar and blood pressure.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-08', 'pcos', 3, 'Good sleep and less stress are part of looking after PCOS.', 'fact', 'Rest helps hormones.', 'True. Sleep and stress affect hormones and energy.', NULL, 'NHS: Polycystic ovary syndrome', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-09', 'pcos', 3, 'People with PCOS have a higher chance of getting type 2 diabetes later in life.', 'fact', 'Remember insulin?', 'Yep! Because of insulin resistance, the risk is higher. Healthy habits and regular check-ups help.', 'A simple blood test can check your blood sugar.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-3-10', 'pcos', 3, 'Laser hair removal makes PCOS worse.', 'myth', 'Does treating hair change your hormones?', 'Nope! Laser and other hair removal treatments don’t affect PCOS. They’re one way to manage extra hair.', 'Some medicines and creams can also slow hair growth.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-01', 'pcos', 4, 'To diagnose PCOS in adults, doctors usually look for 2 out of 3 things: irregular ovulation, signs of high androgens, and polycystic ovaries.', 'fact', 'Two out of three.', 'Correct! These are called the Rotterdam criteria, and other causes are ruled out first.', 'You don’t need a scan if the first two are present.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-02', 'pcos', 4, 'Teenagers are diagnosed with PCOS using an ovary scan.', 'myth', 'Teen ovaries look different.', 'Not true! Ultrasound isn’t recommended for diagnosis within 8 years of a first period, because many healthy teen ovaries look ‘polycystic’.', 'Teens are diagnosed using cycles and androgen signs.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-03', 'pcos', 4, 'PCOS is linked to a higher chance of sleep apnoea.', 'fact', 'Sleep matters too.', 'Correct! Sleep apnoea is more common in PCOS, so snoring and daytime tiredness are worth mentioning.', 'Treating it can help energy and mood.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-04', 'pcos', 4, 'PCOS goes away completely after menopause.', 'myth', 'What about the metabolic side?', 'Not quite! Periods stop, but risks like type 2 diabetes and heart health still need looking after.', 'Regular check-ups remain useful.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-05', 'pcos', 4, 'Metformin, a diabetes medicine, is sometimes used to treat PCOS.', 'fact', 'Insulin helper.', 'Correct! It helps the body use insulin better, which can help some people’s symptoms.', 'It can upset the stomach at first.', 'NHS: PCOS treatment', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-06', 'pcos', 4, 'In PCOS, insulin resistance only happens in people with a higher weight.', 'myth', 'Size isn’t the whole story.', 'Not true! People with PCOS of any weight can have insulin resistance.', 'It’s thought to be part of PCOS itself.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-07', 'pcos', 4, 'Long gaps between periods can let the womb lining build up, so doctors may bring on a regular bleed.', 'fact', 'Lining buildup.', 'Correct! Regular bleeds, often with hormone treatment, protect the womb lining.', 'Three or more bleeds a year is a common aim.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-08', 'pcos', 4, 'PCOS is caused by eating too much sugar.', 'myth', 'Genes or sugar?', 'Not true! PCOS is linked to genes and hormones. Diet can help manage it, but sugar doesn’t cause it.', 'It often runs in families.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-09', 'pcos', 4, 'AMH levels are often higher in people with PCOS.', 'fact', 'More follicles, more AMH.', 'Correct! Many small follicles mean more AMH.', 'AMH is made by small growing follicles.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-4-10', 'pcos', 4, 'Extra hair growth in PCOS is caused by too much oestrogen.', 'myth', 'Which hormone grows hair?', 'Not true! It’s caused by higher androgens like testosterone.', 'Doctors call it hirsutism.', 'NHS: PCOS', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-01', 'pcos', 5, 'The 2023 international PCOS guideline allows an AMH blood test instead of an ultrasound for adults.', 'fact', 'A newer option.', 'Correct! AMH can now stand in for the ovary part of the criteria in adults.', 'It’s not recommended for teens.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-02', 'pcos', 5, 'Polycystic-looking ovaries on a scan mean you definitely have PCOS.', 'myth', 'Common in people without PCOS.', 'Not true! Lots of people without PCOS have ovaries that look polycystic. A scan alone isn’t a diagnosis.', 'That’s why the 2-out-of-3 rule exists.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-03', 'pcos', 5, 'In PCOS, high insulin can lower SHBG, leaving more free testosterone in the blood.', 'fact', 'Remember the hormone taxi?', 'Correct! Less SHBG means more active testosterone, which can worsen acne and hair growth.', 'This is one link between insulin and androgens.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-04', 'pcos', 5, 'Inositol is a proven cure for PCOS.', 'myth', 'Proven or popular?', 'Not true! Inositol is popular, but the guideline says the evidence is limited. Talk to a doctor before trying it.', 'There is no cure for PCOS yet.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-05', 'pcos', 5, 'People with PCOS have a higher chance of gestational diabetes in pregnancy.', 'fact', 'Insulin again.', 'Correct! That’s why pregnant people with PCOS may get early screening.', 'Healthy habits before pregnancy help.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-06', 'pcos', 5, 'PCOS was first described in the 2000s.', 'myth', 'Older than you think.', 'Not true! Stein and Leventhal described it in 1935.', 'It was once called Stein-Leventhal syndrome.', 'Stein and Leventhal, American Journal of Obstetrics and Gynecology (1935)', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-07', 'pcos', 5, 'Up to about 70% of people with PCOS may not be diagnosed.', 'fact', 'Hidden numbers.', 'Correct! Many people don’t know they have it, especially if symptoms are mild.', 'Tracking cycles can help spot it.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-08', 'pcos', 5, 'Metformin works mainly by lowering testosterone directly.', 'myth', 'What does it target?', 'Not true! It mainly helps the body respond to insulin. Any drop in androgens is a knock-on effect.', 'It’s one of the most used medicines worldwide.', 'NHS: Metformin', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-09', 'pcos', 5, 'Having fewer than about 8 periods a year can be a sign of irregular ovulation.', 'fact', 'Counting periods.', 'Correct! Cycles longer than 35 days or fewer than 8 periods a year suggest irregular ovulation in adults.', 'For teens, the rules are a bit different.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('pcos-5-10', 'pcos', 5, 'Losing weight is the only treatment that works for PCOS.', 'myth', 'Many tools.', 'Not true! Medicines, hormone treatments, skin and hair treatments, and mental health support all help.', 'Treatment is tailored to each person’s symptoms.', 'International PCOS Guideline (2023)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-01', 'food-cycle', 1, 'A mix of different foods helps your body all month long.', 'fact', 'Variety is the spice of life.', 'True. Fruit, veg, wholegrains and protein give your body what it needs.', '‘Eating the rainbow’ is an easy way to get variety.', 'NHS: Eat well', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-02', 'food-cycle', 1, 'Skipping meals is a good way to beat bloating.', 'myth', 'Your body needs regular fuel.', 'Myth. Skipping meals can drain your energy and mood. Small, regular meals work better.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-03', 'food-cycle', 1, 'Fruit and veg can help keep your tummy happy on your period.', 'fact', 'Think fibre.', 'True. Fibre keeps digestion moving, which can help with period tummy troubles.', 'Oats, beans and whole fruit are great sources of fibre.', 'NHS: Eat well', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-04', 'food-cycle', 1, 'Your teens are a key time for building strong bones.', 'fact', 'Think milk, yoghurt and leafy greens.', 'True. Calcium helps build bones, and your teens are when you build a lot of bone strength.', 'Your bones reach their peak strength around age 30.', 'NHS: Calcium', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-05', 'food-cycle', 1, 'Wholegrains give you steadier energy than sugary snacks.', 'fact', 'Slow and steady.', 'True. They release energy slowly, so you avoid quick highs and crashes.', 'Brown rice, oats and wholemeal bread are all wholegrains.', 'NHS: Eat well', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-06', 'food-cycle', 1, 'You need special ‘period foods’ to stay healthy.', 'myth', 'Everyday food is enough.', 'Myth. No special foods needed. A normal balanced diet supports your cycle.', NULL, 'NHS: Eat well', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-07', 'food-cycle', 1, 'Drinking enough water still matters on your period.', 'fact', 'Stay topped up.', 'True. Staying hydrated helps your energy and can ease headaches.', 'Water, milk and sugar-free drinks all count towards your fluids.', 'NHS: Water, drinks and your health', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-08', 'food-cycle', 1, 'Cutting out whole food groups is a healthy way to fix period symptoms.', 'myth', 'Balance is key.', 'Myth. You could miss out on nutrients. Talk to a doctor or dietitian first.', NULL, 'NHS: Eat well', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-09', 'food-cycle', 1, 'Milk, yoghurt and fortified plant drinks help build strong bones.', 'fact', 'Which mineral do bones love?', 'Yep! They’re rich in calcium, and your teens are a key time for building bone.', 'Look for ‘fortified with calcium’ on plant drinks.', 'NHS: Calcium', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-1-10', 'food-cycle', 1, 'Drinking water on your period makes bloating worse.', 'myth', 'Does your body hold on to water when it’s short of it?', 'Nope! Staying hydrated can actually help ease bloating.', 'Water-rich foods like cucumber and watermelon count too.', 'Cleveland Clinic: Period bloating', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-01', 'food-cycle', 2, 'Iron is what helps your blood carry oxygen around your body.', 'fact', 'It’s part of your red blood cells.', 'True. Iron is needed to make haemoglobin, the oxygen-carrier in red blood cells.', 'Haemoglobin is what makes blood red.', 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-02', 'food-cycle', 2, 'Heavy periods can leave you low on iron.', 'fact', 'Blood contains iron.', 'True. Losing lots of blood each month can lead to low iron or anaemia.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-03', 'food-cycle', 2, 'Red meat is the only food with iron in it.', 'myth', 'Think plants too.', 'Myth! Beans, lentils, dark leafy greens, nuts and some breakfast cereals have iron too.', 'Iron from plants is absorbed less easily than iron from meat.', 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-04', 'food-cycle', 2, 'Vitamin C helps your body grab more iron from plant foods.', 'fact', 'Think oranges and peppers.', 'True. Pair iron-rich plants with vitamin C foods to absorb more.', 'A glass of orange juice with fortified cereal is an easy combo.', 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-05', 'food-cycle', 2, 'A cup of tea with your meal can make it harder to absorb iron.', 'fact', 'Timing your cuppa matters.', 'True. Tea and coffee can block some iron, so have them between meals.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-06', 'food-cycle', 2, 'Feeling exhausted all the time is just part of having periods.', 'myth', 'Tiredness can have causes.', 'Myth. Some tiredness is common, but constant exhaustion can mean low iron. Worth checking.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-07', 'food-cycle', 2, 'It’s fine to take iron tablets without checking with anyone.', 'myth', 'Too much iron is a problem too.', 'Myth. Too much iron can be harmful. Ask a doctor or pharmacist first.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-08', 'food-cycle', 2, 'Some breakfast cereals have extra iron added.', 'fact', 'Check the label.', 'True. Fortified cereals can be a handy iron boost. Look for iron on the nutrition label.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-09', 'food-cycle', 2, 'Beans, lentils and dark leafy greens all contain iron.', 'fact', 'Is iron only in meat?', 'Yep! Plant foods have iron too. Pair them with vitamin C to help your body absorb it.', 'A squeeze of lemon over greens is an easy iron hack.', 'NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-2-10', 'food-cycle', 2, 'Iron from spinach is absorbed just as easily as iron from meat.', 'myth', 'There are two types of iron.', 'Nope! Iron from plants (non-haem) is harder to absorb than iron from meat and fish (haem).', 'Popeye’s spinach fame came partly from an old maths mix-up about its iron.', 'NIH Office of Dietary Supplements: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-01', 'food-cycle', 3, 'Craving snacks before your period is really common.', 'fact', 'You’re not alone.', 'True. Hormone changes can boost your appetite and cravings.', 'Cravings often ease once your period starts.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-02', 'food-cycle', 3, 'A craving always means your body is missing a nutrient.', 'myth', 'Is there proof?', 'Myth. There’s little evidence for that. Cravings are more likely linked to hormones and mood.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-03', 'food-cycle', 3, 'Salty snacks can make bloating worse.', 'fact', 'Salt holds on to water.', 'True. Salt makes your body hang on to water, adding to pre-period bloat.', 'Lots of salt hides in crisps, ready meals and takeaways.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-04', 'food-cycle', 3, 'Small, regular meals can help keep your mood and energy steady.', 'fact', 'Think little and often.', 'True. Eating little and often can help with tiredness and irritability.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-05', 'food-cycle', 3, 'Fizzy drinks help beat the bloat.', 'myth', 'Think about the bubbles.', 'Myth. All those bubbles can add gas and make bloating feel worse.', 'Still water or herbal tea is a gentler choice.', NULL, 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-06', 'food-cycle', 3, 'Eating chocolate on your period is bad for you.', 'myth', 'Enjoy in balance.', 'Myth. Chocolate is fine as part of a balanced diet. No guilt needed.', 'Dark chocolate even contains a little iron.', 'NHS: Eat well', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-07', 'food-cycle', 3, 'Too much caffeine can make you feel more jittery before your period.', 'fact', 'Think coffee and energy drinks.', 'True. Cutting down may help if you feel anxious or can’t sleep before your period.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-08', 'food-cycle', 3, 'Pre-period bloating happens because you ate too much.', 'myth', 'Hormones are the main reason.', 'Myth. Hormone changes make your body hold on to water. That’s most of the bloat.', 'Bloating usually eases once your period starts.', 'NHS: Premenstrual syndrome (PMS)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-09', 'food-cycle', 3, 'Chamomile tea has been proven to cure period pain.', 'myth', 'Proven or soothing?', 'Not proven! A warm drink can feel comforting, but there isn’t strong evidence that it cures cramps.', 'Heat on your tummy has better evidence.', 'NHS: Period pain', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-3-10', 'food-cycle', 3, 'A very sugary snack can give a quick lift followed by a slump.', 'fact', 'What goes up...', 'Yep! Sugary foods can give a short burst of energy. Snacks with fibre or protein keep you going for longer.', 'Fruit with a handful of nuts is a steadier choice.', 'NHS: Eat well', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-01', 'food-cycle', 4, 'Girls aged 11 to 18 in the UK are advised to get 14.8 mg of iron a day.', 'fact', 'A number to remember.', 'Correct! That’s much more than younger children need, because periods mean losing iron.', 'Boys of the same age need 11.3 mg.', 'NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-02', 'food-cycle', 4, 'Haem iron comes from plants.', 'myth', 'Haem, like haemoglobin.', 'Not true! Haem iron comes from meat and fish. Plant iron is called non-haem iron.', 'Haem iron is absorbed more easily.', 'NIH Office of Dietary Supplements: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-03', 'food-cycle', 4, 'Calcium taken with an iron-rich meal can reduce how much iron you absorb.', 'fact', 'Minerals compete.', 'Correct! Calcium can block iron absorption, so space supplements apart if you take both.', 'Food sources together are less of a concern.', 'NIH Office of Dietary Supplements: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-04', 'food-cycle', 4, 'Vitamin D is mostly found in fruit.', 'myth', 'Where does vitamin D come from?', 'Not true! Most vitamin D comes from sunlight on skin, plus oily fish, eggs and fortified foods.', 'It’s sometimes called the sunshine vitamin.', 'NHS: Vitamin D', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-05', 'food-cycle', 4, 'In the UK, everyone is advised to consider a vitamin D supplement in autumn and winter.', 'fact', 'Less sun, less D.', 'Correct! There isn’t enough sunlight in UK winters to make enough vitamin D.', 'People with darker skin may need it all year.', 'NHS: Vitamin D', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-06', 'food-cycle', 4, 'Folate is found in leafy greens, beans and fortified cereals.', 'fact', 'B9.', 'Correct! Folate helps make healthy red blood cells.', 'Folic acid is the man-made form.', 'NHS: B vitamins and folic acid', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-07', 'food-cycle', 4, 'Omega-3 fats are only found in fish.', 'myth', 'Seeds?', 'Not true! Flaxseed, chia seeds and walnuts have a plant form of omega-3.', 'The body converts only a small amount of it.', 'NHS: Fish and shellfish', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-08', 'food-cycle', 4, 'Iron needs go up once periods start.', 'fact', 'Why?', 'Correct! Periods mean losing blood, and blood holds iron.', 'Younger girls need about 8.7 mg a day.', 'NHS: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-09', 'food-cycle', 4, 'Taking more vitamins than you need is always harmless.', 'myth', 'Too much of a good thing?', 'Not true! Some vitamins and minerals, like vitamin A and iron, can be harmful in high doses.', 'Stick to recommended amounts.', 'NHS: Vitamins and minerals', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-4-10', 'food-cycle', 4, 'Sugar cravings before your period prove your blood sugar is low.', 'myth', 'Proof?', 'Not true! Cravings are common in PMS, but they don’t prove low blood sugar.', 'Hormone shifts can change appetite.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-01', 'food-cycle', 5, 'Phytates in wholegrains and beans can reduce iron absorption, and soaking or sprouting can help.', 'fact', 'Kitchen tricks.', 'Correct! Soaking and sprouting lower phytates, so more iron gets absorbed.', 'Fermenting foods also helps.', 'NIH Office of Dietary Supplements: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-02', 'food-cycle', 5, 'Ferritin goes up when your iron stores are low.', 'myth', 'Stores and readings.', 'Not true! Low ferritin means low iron stores.', 'It’s often the first test to drop.', 'NHS: Ferritin test', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-03', 'food-cycle', 5, 'An infection or inflammation can make ferritin look higher than your true iron stores.', 'fact', 'Misleading results.', 'Correct! Ferritin rises with inflammation, so doctors look at other results too.', 'Doctors call this an acute-phase reactant.', 'NIH Office of Dietary Supplements: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-04', 'food-cycle', 5, 'Vitamin B12 is found naturally in most plant foods.', 'myth', 'Where does B12 come from?', 'Not true! B12 is naturally found in animal foods. Vegans need fortified foods or supplements.', 'B12 is made by bacteria.', 'NHS: Vitamin B12', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-05', 'food-cycle', 5, 'Eating too little for how much you train can lower oestrogen and weaken bones.', 'fact', 'Energy budget.', 'Correct! Low energy availability can stop periods and reduce bone strength.', 'It’s part of RED-S.', 'NHS: Stopped or missed periods', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-06', 'food-cycle', 5, 'The calcium in spinach is absorbed as easily as the calcium in milk.', 'myth', 'Spinach has a catch.', 'Not true! Spinach contains oxalates that bind calcium, so very little is absorbed.', 'Kale and broccoli are better plant sources.', 'NIH Office of Dietary Supplements: Calcium', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-07', 'food-cycle', 5, 'Iron taken every other day can be absorbed as well as, or better than, daily doses.', 'fact', 'Hepcidin is involved.', 'Correct! A daily dose raises hepcidin, which blocks absorption the next day. Always follow your doctor’s advice.', 'Some doctors now prescribe alternate-day iron.', 'Stoffel et al., Lancet Haematology (2017)', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-08', 'food-cycle', 5, 'Hepcidin is a hormone that helps you absorb more iron.', 'myth', 'Gatekeeper.', 'Not true! Hepcidin blocks iron absorption when stores are full or there’s inflammation.', 'It’s made in the liver.', 'NIH Office of Dietary Supplements: Iron', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-09', 'food-cycle', 5, 'Calcium may help ease some PMS symptoms.', 'fact', 'Bones and moods?', 'Correct! Some research suggests calcium can help PMS symptoms.', 'Food sources are a good place to start.', 'ACOG: Premenstrual syndrome', 'approved', 'Spot it content team', true, now()),
  ('food-cycle-5-10', 'food-cycle', 5, 'Craving ice is never linked to low iron.', 'myth', 'Strange cravings.', 'Not true! Craving ice, called pagophagia, can be a sign of iron deficiency.', 'It often stops once iron levels are treated.', 'NHS: Iron deficiency anaemia', 'approved', 'Spot it content team', true, now())
